      for (const type of EVENT_ORDER) {
        const s = this.schedules[type];
        if (!s.armed) continue;
        if (!best || s.next < best.next) best = { type, next: s.next, ...s };
      }
      return best;
    }

    snapshot() {
      return {
        seed: this.seed,
        gen: this.gen,
        target: this.target,
        done: this.done,
        finishReason: this.finishReason,
        counts: { prey: this.prey.length, predator: this.predators.length },
        plantCover: this.cover,
        plantBiomass: this.biomass,
        mutation: this.mutation,
        regrowth: this.regrowth,
        activeEvents: this.activeEvents.map((e) => ({ type: e.type, start: e.start, end: e.end })),
        next: this.nextEvent(),
        stats: this.stats,
        schedules: JSON.parse(JSON.stringify(this.schedules)),
      };
    }

    summary() {
      const first = (arr) => arr.find((v) => v !== null && v !== undefined);
      const last = (arr) => {
        for (let i = arr.length - 1; i >= 0; i--) if (arr[i] !== null && arr[i] !== undefined) return arr[i];
        return null;
      };
      const traits = {};
