          const store = this.history.traits[sp][gene.key];
          const start = first(store.mean);
          const end = last(store.mean);
          const startSd = first(store.sd);
          const endSd = last(store.sd);
          traits[sp][gene.key] = { start, end, startSd, endSd, delta: start === null || end === null ? null : end - start };
