      return {
        seed: this.seed,
        target: this.target,
        gen: this.gen,
        done: this.done,
        finishReason: this.finishReason,
        history: this.history,
        events: this.events.map((e) => ({ type: e.type, start: e.start, end: e.end, num: e.num, name: e.name, completed: !!e.completed })),
        stats: this.stats,
        counts: { prey: this.prey.length, predator: this.predators.length },
        plantCover: this.cover,
        traits,
        config: JSON.parse(JSON.stringify(this.config)),
      };
    }
  }

  function createWorld(config) {
    return new World(config);
  }

  function runHeadless(input = {}) {
    const config = normalizeConfig(input);
    const world = new World(config);
    let guard = config.generations * TICKS_PER_GEN + TICKS_PER_GEN;
    while (!world.done && guard-- > 0) world.step();
    return world.summary();
  }

  return {
    W, H, CELLS, TICKS_PER_GEN, GENE_DEFS, SPECIES, EVENT_DEFS, EVENT_ORDER,
    DEFAULTS, Random, World, createWorld, runHeadless, normalizeConfig,
  };
