   VIVARIUM No. IV — simulation core
   Pure simulation. No DOM, no canvas, no timers. Same seed => same world.
   ========================================================================= */
const VIVARIUM_SIM = (() => {
  'use strict';

  const W = 128;
  const H = 80;
  const CELLS = W * H;
  const TICKS_PER_GEN = 12;
  const MAX_PREY = 820;
  const MAX_PREDATOR = 170;

  const GENE_DEFS = [
    { key: 'speed', name: 'Speed', short: 'SPD', unit: 'cells/tick', min: 0.2, max: 2.2, decimals: 2, drift: 0.22 },
    { key: 'vision', name: 'Vision', short: 'VIS', unit: 'cells', min: 3, max: 26, decimals: 1, drift: 0.24 },
    { key: 'metabolism', name: 'Metabolism', short: 'MET', unit: '×', min: 0.4, max: 2.0, decimals: 2, drift: 0.20 },
    { key: 'repro', name: 'Repro. threshold', short: 'RPR', unit: 'energy', min: 20, max: 180, decimals: 0, drift: 0.26 },
  ];

  const SPECIES = {
    prey: {
      key: 'prey', plural: 'moths', name: 'Moth', color: '#e2bd7b', max: MAX_PREY,
      initCount: 174, initEnergy: [28, 48], reproCooldown: 26,
      init: { speed: [0.55, 0.16], vision: [10.5, 2.2], metabolism: [1.0, 0.12], repro: [40, 4.5] },
      lifespan: [620, 400],
      baseCost: 0.05, speedCost: 0.047, visionCost: 0.0028,
    },
    predator: {
      key: 'predator', plural: 'shrikes', name: 'Shrike', color: '#d8715b', max: MAX_PREDATOR,
      initCount: 34, initEnergy: [86, 124], reproCooldown: 76,
      init: { speed: [0.92, 0.16], vision: [15.5, 2.6], metabolism: [1.0, 0.12], repro: [106, 11] },
      lifespan: [850, 480],
      baseCost: 0.085, speedCost: 0.06, visionCost: 0.0037,
    },
  };

  const EVENT_DEFS = {
    drought: {
      key: 'drought', num: 'I', name: 'Drought', color: '#d0a15f',
      duration: 14, defaultInterval: 55,
      note: 'the water table recedes; the verdure dims',
    },
    plague: {
      key: 'plague', num: 'II', name: 'Plague', color: '#a99bc4',
      duration: 12, defaultInterval: 85,
      note: 'a violet fever moves through the moths',
    },
    bloom: {
      key: 'bloom', num: 'III', name: 'Bloom', color: '#6fb9a2',
      duration: 16, defaultInterval: 115,
      note: 'the glass turns green; sight drowns in spores',
    },
  };

  const EVENT_ORDER = ['drought', 'plague', 'bloom'];
  const GENE_KEYS = GENE_DEFS.map((g) => g.key);

  const DEFAULTS = {
    seed: 4407,
    mutation: 8,       // percent per birth
    regrowth: 5.5,     // percent per tick
    generations: 240,
    catastrophes: {
      drought: { interval: 55, armed: true },
      plague: { interval: 85, armed: true },
      bloom: { interval: 115, armed: true },
    },
  };

  const clamp = (v, lo, hi) => (v < lo ? lo : v > hi ? hi : v);

  class Random {
    constructor(seed) {
      this.state = (seed >>> 0) || 0x9e3779b9;
      this._spare = null;
    }
    next() {
      let a = this.state = (this.state + 0x6d2b79f5) | 0;
      let t = Math.imul(a ^ (a >>> 15), 1 | a);
      t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
      return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    }
    range(lo, hi) { return lo + (hi - lo) * this.next(); }
    int(n) { return Math.floor(this.next() * n); }
    gauss() {
      if (this._spare !== null) {
        const spare = this._spare;
        this._spare = null;
        return spare;
      }
      let u = 0;
      let v = 0;
      while (u === 0) u = this.next();
      while (v === 0) v = this.next();
      const mag = Math.sqrt(-2 * Math.log(u));
      this._spare = mag * Math.sin(2 * Math.PI * v);
      return mag * Math.cos(2 * Math.PI * v);
    }
  }

  function normalizeConfig(input = {}) {
    const cfg = {
      seed: Number.isFinite(+input.seed) ? Math.max(1, Math.floor(+input.seed)) : DEFAULTS.seed,
      mutation: Number.isFinite(+input.mutation) ? clamp(+input.mutation, 0, 24) : DEFAULTS.mutation,
      regrowth: Number.isFinite(+input.regrowth) ? clamp(+input.regrowth, 0.5, 14) : DEFAULTS.regrowth,
      generations: Number.isFinite(+input.generations) ? Math.round(clamp(+input.generations, 20, 2000)) : DEFAULTS.generations,
      catastrophes: {},
    };
    for (const type of EVENT_ORDER) {
      const src = input.catastrophes && input.catastrophes[type] ? input.catastrophes[type] : {};
      cfg.catastrophes[type] = {
        interval: Number.isFinite(+src.interval) ? Math.round(clamp(+src.interval, 15, 400)) : DEFAULTS.catastrophes[type].interval,
        armed: src.armed === undefined ? DEFAULTS.catastrophes[type].armed : !!src.armed,
      };
    }
    return cfg;
  }

  function makeHistory() {
    const traits = {};
    for (const key of ['prey', 'predator']) {
      traits[key] = {};
      for (const g of GENE_KEYS) traits[key][g] = { mean: [], sd: [] };
    }
    return {
      gen: [], flora: [], prey: [], predator: [],
      preyPeak: 0, predatorPeak: 0,
      traits,
    };
  }

  function newGeneSet(rng, speciesKey) {
    const def = SPECIES[speciesKey];
    const genes = {};
    for (const g of GENE_DEFS) {
      const init = def.init[g.key];
      genes[g.key] = clamp(init[0] + rng.gauss() * init[1], g.min, g.max);
    }
    return genes;
  }

  function mutateGenes(genes, rng, mutation) {
    const child = {};
    for (const g of GENE_DEFS) {
      const span = g.max - g.min;
      const step = rng.gauss() * (mutation / 100) * span * g.drift;
      child[g.key] = clamp(genes[g.key] + step, g.min, g.max);
    }
    return child;
  }

  function plantNoise(rng) {
    const gw = 18;
    const gh = 12;
    const grid = new Float32Array(gw * gh);
    for (let i = 0; i < grid.length; i++) grid[i] = rng.next();
    const smooth = (t) => t * t * (3 - 2 * t);
    const sample = (u, v) => {
      const x = u * (gw - 1);
      const y = v * (gh - 1);
      const x0 = Math.floor(x);
      const y0 = Math.floor(y);
      const x1 = Math.min(gw - 1, x0 + 1);
      const y1 = Math.min(gh - 1, y0 + 1);
      const fx = smooth(x - x0);
      const fy = smooth(y - y0);
      const a = grid[y0 * gw + x0] + (grid[y0 * gw + x1] - grid[y0 * gw + x0]) * fx;
      const b = grid[y1 * gw + x0] + (grid[y1 * gw + x1] - grid[y1 * gw + x0]) * fx;
      return a + (b - a) * fy;
    };
    return sample;
  }

  class World {
    constructor(input = {}) {
      this.config = normalizeConfig(input);
      this.seed = this.config.seed;
      this.rng = new Random(this.seed);
      this.mutation = this.config.mutation;
      this.regrowth = this.config.regrowth;
      this.target = this.config.generations;
      this.gen = 0;
      this.tickInGen = 0;
      this.done = false;
      this.finishReason = null;
      this.plants = new Float32Array(CELLS);
      this.activeEvents = [];
      this.events = [];
      this.schedules = {};
      for (const type of EVENT_ORDER) {
        const src = this.config.catastrophes[type];
        this.schedules[type] = {
          interval: src.interval,
          armed: src.armed,
          next: src.interval,
          duration: EVENT_DEFS[type].duration,
        };
      }
      this.stats = {
        births: { prey: 0, predator: 0 },
        deaths: { prey: { starve: 0, age: 0, preyed: 0, plague: 0 }, predator: { starve: 0, age: 0 } },
        infections: 0,
        catastrophes: 0,
        ticks: 0,
      };
      this.history = makeHistory();
      this._initFlora();
      this._initAgents();
      this.record();
      this._uid = 1;
    }

    _initFlora() {
      const noise = plantNoise(this.rng);
      const threshold = 0.42;
      for (let y = 0; y < H; y++) {
        for (let x = 0; x < W; x++) {
          const u = x / (W - 1);
          const v = y / (H - 1);
          const n = noise(u + 0.08, v + 0.04) * 0.66 + noise(u * 0.48 + 0.4, v * 0.52 + 0.2) * 0.34;
          const grain = this.rng.next() * 0.1;
          let b = (n + grain - threshold) / 0.26;
          b = clamp(b, 0, 1);
          b = b * b * (3 - 2 * b);
          this.plants[y * W + x] = b * (0.4 + this.rng.next() * 0.6);
        }
      }
      this._updatePlantStats();
    }

    _makeAgent(speciesKey, x, y, genes, energy) {
      const def = SPECIES[speciesKey];
      const rng = this.rng;
      return {
        uid: this._uid++,
        species: speciesKey,
        x, y,
        dir: rng.range(0, Math.PI * 2),
        genes: genes || newGeneSet(rng, speciesKey),
        energy: energy === undefined ? rng.range(def.initEnergy[0], def.initEnergy[1]) : energy,
        age: 0,
        lifespan: def.lifespan[0] + rng.next() * def.lifespan[1],
        lastBirth: -999,
        infected: false,
        dead: false,
        hits: 0,
        meals: 0,
      };
    }

    _initAgents() {
      this.prey = [];
      this.predators = [];
      for (let i = 0; i < SPECIES.prey.initCount; i++) {
        this.prey.push(this._makeAgent('prey', this.rng.range(1, W - 1), this.rng.range(1, H - 1)));
      }
      for (let i = 0; i < SPECIES.predator.initCount; i++) {
        this.predators.push(this._makeAgent('predator', this.rng.range(1, W - 1), this.rng.range(1, H - 1)));
      }
    }

    _updatePlantStats() {
      let sum = 0;
      let covered = 0;
      for (let i = 0; i < CELLS; i++) {
        const b = this.plants[i];
        sum += b;
        if (b > 0.06) covered++;
      }
      this.biomass = sum;
      this.cover = covered / CELLS;
    }

    plantAt(x, y) {
      const px = clamp(Math.floor(x), 0, W - 1);
      const py = clamp(Math.floor(y), 0, H - 1);
      return this.plants[py * W + px];
    }

    _effects() {
      const e = {
        regrowth: 1, wither: 0, vision: 1, cost: 1, preyHazard: 0, tint: null,
      };
      for (const ev of this.activeEvents) {
        if (ev.type === 'drought') {
          e.regrowth *= 0.12;
          e.wither += 0.0016;
          e.cost *= 1.04;
        } else if (ev.type === 'plague') {
          e.preyHazard += 0.0022;
          e.cost *= 1.02;
        } else if (ev.type === 'bloom') {
          e.regrowth *= 2.35;
          e.vision *= 0.56;
          e.cost *= 1.12;
        }
      }
      if (this.activeEvents.length) e.tint = this.activeEvents[this.activeEvents.length - 1].type;
      return e;
    }

    _nearest(list, x, y, maxDist, skipDead = true) {
      let best = null;
      let bestD = maxDist * maxDist;
      for (let i = 0; i < list.length; i++) {
        const a = list[i];
        if (skipDead && a.dead) continue;
        const dx = a.x - x;
        const dy = a.y - y;
        const d = dx * dx + dy * dy;
        if (d < bestD) {
          bestD = d;
          best = a;
        }
      }
      return best ? { agent: best, dist: Math.sqrt(bestD) } : null;
    }

    _plantProbe(agent, angle, effects) {
      const vision = agent.genes.vision;
      let score = 0;
      for (let d = 1; d <= 3; d++) {
        const reach = 0.4 + (vision * d) / 3.2;
        const px = agent.x + Math.cos(angle) * reach;
        const py = agent.y + Math.sin(angle) * reach;
        score += this.plantAt(px, py) * (1.2 - d * 0.22);
      }
      return score;
    }

    _stepPrey(effects) {
      const rng = this.rng;
      const initial = this.prey.length;
      for (let i = 0; i < initial; i++) {
        const p = this.prey[i];
        if (p.dead) continue;
        const genes = p.genes;
        const speed = genes.speed * (effects.vision < 1 ? 0.94 : 1);
        p.age++;

        const threat = this._nearest(this.predators, p.x, p.y, genes.vision * 0.9);
        const danger = threat && threat.dist < genes.vision * 0.72;

        let desired = p.dir;
        if (danger) {
          desired = Math.atan2(p.y - threat.agent.y, p.x - threat.agent.x) + rng.gauss() * 0.12;
        } else {
          let bestScore = -Infinity;
          for (let k = -2; k <= 2; k++) {
