            let score = this._plantProbe(p, angle, effects);
            if (k === 0) score += 0.22;
            score -= Math.abs(k) * 0.035;
            score += rng.gauss() * 0.015;
            if (score > bestScore) {
              bestScore = score;
              desired = angle;
            }
          }
        }

        let turn = Math.atan2(Math.sin(desired - p.dir), Math.cos(desired - p.dir));
        const maxTurn = danger ? 0.9 : 0.42;
        p.dir += clamp(turn + rng.gauss() * 0.055, -maxTurn, maxTurn);

        let nx = p.x + Math.cos(p.dir) * speed;
        let ny = p.y + Math.sin(p.dir) * speed;
        if (nx < 0.6 || nx > W - 0.6) {
          p.dir = Math.PI - p.dir;
          nx = clamp(nx, 0.6, W - 0.6);
        }
        if (ny < 0.6 || ny > H - 0.6) {
          p.dir = -p.dir;
          ny = clamp(ny, 0.6, H - 0.6);
        }
        p.x = nx;
        p.y = ny;

        const cellX = clamp(Math.floor(nx), 0, W - 1);
        const cellY = clamp(Math.floor(ny), 0, H - 1);
        const idx = cellY * W + cellX;
        const available = this.plants[idx];
        let ate = 0;
        if (available > 0.035) {
          ate = Math.min(available, 0.022 + speed * 0.018);
          this.plants[idx] = available - ate;
          p.energy += ate * 22 * (0.62 + 0.38 * genes.metabolism);
        }

        let cost = (SPECIES.prey.baseCost + genes.speed * SPECIES.prey.speedCost + genes.vision * SPECIES.prey.visionCost)
          * (0.52 + 0.62 * genes.metabolism) * effects.cost;
