          p.cause = 'age';
          this.stats.deaths.prey.age++;
          continue;
        }

        if (p.energy >= genes.repro && p.age - p.lastBirth > SPECIES.prey.reproCooldown && this.prey.length < MAX_PREY) {
          this._birth(p, 'prey');
        }
      }

      this._compact('prey');
    }

    _birth(parent, speciesKey) {
      const rng = this.rng;
      const def = SPECIES[speciesKey];
      const genes = mutateGenes(parent.genes, rng, this.mutation);
      const inheritance = 0.42;
      const energy = parent.energy * inheritance;
      parent.energy -= energy;
      parent.lastBirth = parent.age;
      const child = this._makeAgent(
        speciesKey,
        clamp(parent.x + rng.gauss() * 1.15, 0.8, W - 0.8),
        clamp(parent.y + rng.gauss() * 1.15, 0.8, H - 0.8),
        genes,
        energy
      );
      child.age = 0;
      child.lifespan = def.lifespan[0] + rng.next() * def.lifespan[1];
      if (speciesKey === 'prey') this.prey.push(child);
      else this.predators.push(child);
      this.stats.births[speciesKey]++;
      if (speciesKey === 'prey' && rng.next() < 0.02) child.infected = false;
    }

    _stepPredators(effects) {
      const rng = this.rng;
      const initial = this.predators.length;
      for (let i = 0; i < initial; i++) {
        const a = this.predators[i];
        if (a.dead) continue;
        const genes = a.genes;
        a.age++;
        a.hits = Math.max(0, a.hits - 1);

        const target = this._nearest(this.prey, a.x, a.y, genes.vision, true);
        let desired = a.dir;
        if (target) {
          desired = Math.atan2(target.agent.y - a.y, target.agent.x - a.x);
        } else {
          desired = a.dir + Math.sin(a.uid * 1.7 + this.gen * 0.09) * 0.55 + rng.gauss() * 0.13;
        }

        const turn = Math.atan2(Math.sin(desired - a.dir), Math.cos(desired - a.dir));
        a.dir += clamp(turn + rng.gauss() * 0.04, -0.6, 0.6);

        const speed = genes.speed * (target ? 1 : 0.62);
        let nx = a.x + Math.cos(a.dir) * speed;
        let ny = a.y + Math.sin(a.dir) * speed;
        if (nx < 0.6 || nx > W - 0.6) {
          a.dir = Math.PI - a.dir;
          nx = clamp(nx, 0.6, W - 0.6);
        }
        if (ny < 0.6 || ny > H - 0.6) {
          a.dir = -a.dir;
          ny = clamp(ny, 0.6, H - 0.6);
        }
        a.x = nx;
        a.y = ny;

        if (target && a.hits === 0) {
          const live = target.agent;
          if (!live.dead) {
            const dx = live.x - a.x;
            const dy = live.y - a.y;
            const catchDist = 0.72 + genes.speed * 0.16;
            if (dx * dx + dy * dy <= catchDist * catchDist && rng.next() < 0.82) {
              live.dead = true;
              live.cause = 'preyed';
              this.stats.deaths.prey.preyed++;
              a.energy += 40 + clamp(live.energy * 0.34, 0, 34);
              a.hits = 22;
              a.meals++;
            }
          }
        }

        const cost = (SPECIES.predator.baseCost + genes.speed * SPECIES.predator.speedCost + genes.vision * SPECIES.predator.visionCost)
          * (0.55 + 0.5 * genes.metabolism) * effects.cost;
        a.energy -= cost;

        if (a.energy <= 0) {
          a.dead = true;
          a.cause = 'starve';
          this.stats.deaths.predator.starve++;
          continue;
        }
        if (a.age > a.lifespan) {
          a.dead = true;
          a.cause = 'age';
          this.stats.deaths.predator.age++;
          continue;
        }

        if (a.energy >= genes.repro && a.age - a.lastBirth > SPECIES.predator.reproCooldown && this.predators.length < MAX_PREDATOR) {
          this._birth(a, 'predator');
        }
      }

      this._compact('predator');
    }

    _compact(speciesKey) {
      const list = speciesKey === 'prey' ? this.prey : this.predators;
      let write = 0;
      for (let read = 0; read < list.length; read++) {
        if (!list[read].dead) list[write++] = list[read];
      }
      list.length = write;
    }

    _startEvent(type) {
      const def = EVENT_DEFS[type];
      const event = {
        type,
        start: this.gen,
        end: this.gen + def.duration,
        num: def.num,
        name: def.name,
      };
      this.events.push(event);
      this.activeEvents.push(event);
      this.stats.catastrophes++;
      if (type === 'plague') {
        let infected = 0;
        for (const p of this.prey) {
          if (!p.dead && this.rng.next() < 0.23) {
            p.infected = true;
            infected++;
          }
        }
        this.stats.infections += infected;
      }
      return event;
    }

    _endEvents() {
      if (!this.activeEvents.length) return;
      const remaining = [];
      for (const e of this.activeEvents) {
        if (this.gen >= e.end) {
          e.completed = true;
        } else {
          remaining.push(e);
        }
      }
      this.activeEvents = remaining;
    }

    _advanceGeneration() {
      this.gen++;
      this._endEvents();
      for (const type of EVENT_ORDER) {
        const s = this.schedules[type];
        if (!s.armed) continue;
        if (this.gen >= s.next) {
          this._startEvent(type);
          s.next = this.gen + s.interval;
        }
      }
      this._updatePlantStats();
      this.record();
      if (this.gen >= this.target) {
        this.done = true;
        this.finishReason = 'horizon';
      }
    }

    step() {
      if (this.done) return this;
      const effects = this._effects();
      const growth = (this.regrowth / 100) * effects.regrowth;

      for (let i = 0; i < CELLS; i++) {
        let b = this.plants[i];
        b += growth * (1 - b) * (0.18 + 0.82 * b);
        if (effects.wither) b *= 1 - effects.wither;
        this.plants[i] = b < 0.0002 ? 0 : b;
      }

      this._stepPrey(effects);
      this._stepPredators(effects);

      this.stats.ticks++;
      this.tickInGen++;
      if (this.tickInGen >= TICKS_PER_GEN) {
        this.tickInGen = 0;
        this._advanceGeneration();
      }
      return this;
    }

    record() {
      const h = this.history;
      h.gen.push(this.gen);
      h.flora.push(+(this.cover * 100).toFixed(2));
      h.prey.push(this.prey.length);
      h.predator.push(this.predators.length);
      h.preyPeak = Math.max(h.preyPeak, this.prey.length);
      h.predatorPeak = Math.max(h.predatorPeak, this.predators.length);
      for (const sp of ['prey', 'predator']) {
        const list = sp === 'prey' ? this.prey : this.predators;
        for (const gene of GENE_DEFS) {
          const key = gene.key;
          const store = h.traits[sp][key];
          if (!list.length) {
            store.mean.push(null);
            store.sd.push(null);
            continue;
          }
          let mean = 0;
          for (let i = 0; i < list.length; i++) mean += list[i].genes[key];
          mean /= list.length;
          let variance = 0;
          for (let i = 0; i < list.length; i++) {
            const d = list[i].genes[key] - mean;
            variance += d * d;
          }
          store.mean.push(+mean.toFixed(4));
          store.sd.push(+Math.sqrt(variance / list.length).toFixed(4));
        }
      }
    }

    setMutation(value) { this.mutation = clamp(+value, 0, 24); this.config.mutation = this.mutation; }
    setRegrowth(value) { this.regrowth = clamp(+value, 0.5, 14); this.config.regrowth = this.regrowth; }
    setTarget(value) {
      this.target = Math.round(clamp(+value, 20, 2000));
      this.config.generations = this.target;
      if (this.gen >= this.target && !this.done) {
        this.done = true;
        this.finishReason = 'horizon';
      }
    }
    setSchedule(type, { interval, armed } = {}) {
      const s = this.schedules[type];
      if (!s) return;
      if (interval !== undefined) {
        s.interval = Math.round(clamp(+interval, 15, 400));
        s.next = this.gen + s.interval;
        this.config.catastrophes[type].interval = s.interval;
      }
      if (armed !== undefined) {
        s.armed = !!armed;
        this.config.catastrophes[type].armed = s.armed;
      }
    }
    triggerEvent(type) {
      if (!EVENT_DEFS[type]) return null;
      return this._startEvent(type);
    }

    nextEvent() {
      let best = null;
      for (const type of EVENT_ORDER) {
        const s = this.schedules[type];
        if (!s.armed) continue;
        if (!best || s.next < best.next) best = { type, next: s.next, ...s };
      }
      return best;
    }

    snapshot() {
      return {
        seed: this.seed,
        gen: this.gen,
        target: this.target,
        done: this.done,
        finishReason: this.finishReason,
        counts: { prey: this.prey.length, predator: this.predators.length },
        plantCover: this.cover,
        plantBiomass: this.biomass,
        mutation: this.mutation,
        regrowth: this.regrowth,
        activeEvents: this.activeEvents.map((e) => ({ type: e.type, start: e.start, end: e.end })),
        next: this.nextEvent(),
        stats: this.stats,
        schedules: JSON.parse(JSON.stringify(this.schedules)),
      };
    }

    summary() {
      const first = (arr) => arr.find((v) => v !== null && v !== undefined);
      const last = (arr) => {
        for (let i = arr.length - 1; i >= 0; i--) if (arr[i] !== null && arr[i] !== undefined) return arr[i];
        return null;
      };
      const traits = {};
      for (const sp of ['prey', 'predator']) {
        traits[sp] = {};
        for (const gene of GENE_DEFS) {
          const store = this.history.traits[sp][gene.key];
          const start = first(store.mean);
          const end = last(store.mean);
          const startSd = first(store.sd);
          const endSd = last(store.sd);
          traits[sp][gene.key] = { start, end, startSd, endSd, delta: start === null || end === null ? null : end - start };
        }
      }
      return {
        seed: this.seed,
        target: this.target,
        gen: this.gen,
        done: this.done,
        finishReason: this.finishReason,
        history: this.history,
        events: this.events.map((e) => ({ type: e.type, start: e.start, end: e.end, num: e.num, name: e.name, completed: !!e.completed })),
        stats: this.stats,
        counts: { prey: this.prey.length, predator: this.predators.length },
        plantCover: this.cover,
        traits,
        config: JSON.parse(JSON.stringify(this.config)),
      };
    }
  }

  function createWorld(config) {
    return new World(config);
  }

  function runHeadless(input = {}) {
    const config = normalizeConfig(input);
    const world = new World(config);
    let guard = config.generations * TICKS_PER_GEN + TICKS_PER_GEN;
    while (!world.done && guard-- > 0) world.step();
    return world.summary();
  }

  return {
    W, H, CELLS, TICKS_PER_GEN, GENE_DEFS, SPECIES, EVENT_DEFS, EVENT_ORDER,
    DEFAULTS, Random, World, createWorld, runHeadless, normalizeConfig,
  };
})();

if (typeof module !== 'undefined' && module.exports) module.exports = VIVARIUM_SIM;
"}

