{"content": "const SIM = require('./sim.js');

function run(seed, gens = 240, overrides = {}) {
  const t0 = performance.now();
  const rec = SIM.runHeadless({
    seed,
    generations: gens,
    mutation: 8,
    regrowth: 5.5,
    ...overrides,
  });
  const t1 = performance.now();
  const h = rec.history;
  console.log(`\nseed ${seed} · ${gens} gens · ${(t1 - t0).toFixed(1)}ms · target ${rec.target} reached ${rec.gen}`);
  let last = -1;
  for (let i = 0; i < h.gen.length; i++) {
    const g = h.gen[i];
    if (g % 20 !== 0) continue;
    console.log(
      String(g).padStart(3),
      'flora', h.flora[i].toFixed(1).padStart(5),
      'prey', String(h.prey[i]).padStart(3),
      'pred', String(h.predator[i]).padStart(3),
      '| prey spd', h.traits.prey.speed.mean[i]?.toFixed(2),
      'vis', h.traits.prey.vision.mean[i]?.toFixed(1),
      'met', h.traits.prey.metabolism.mean[i]?.toFixed(2),
      'rpr', h.traits.prey.repro.mean[i]?.toFixed(1),
      '| pred spd', h.traits.predator.speed.mean[i]?.toFixed(2),
      'vis', h.traits.predator.vision.mean[i]?.toFixed(1),
    );
  }
  return rec;
}

for (const seed of [4407, 1, 2, 99]) {
  run(seed, 240);
}

