const SIM = require('./sim.js');
const P = SIM.SPECIES.prey, D = SIM.SPECIES.predator;
Object.assign(P, {max: 900, initCount: 140, reproCooldown: 48, energyDensity: 6, biteBase: 0.03, biteSpeed: 0.02,
  baseCost:0.04, speedCost:0.03, visionCost:0.002, birthShare:0.42,
  init:{ speed:[0.55,0.16], vision:[10.5,2.2], metabolism:[1,0.12], repro:[45,4.5] }, lifespan:[700,350]});
const BASE_D = {max: 240, initCount: 8, initEnergy:[110,155], reproCooldown:420, attackCooldown:130, catchChance:0.58,
  killBase:34, killShare:0.25, birthShare:0.34, baseCost:0.08, speedCost:0.05, visionCost:0.003,
  init:{speed:[0.92,0.16],vision:[12,2],metabolism:[1,0.12],repro:[160,12]}, lifespan:[900,480]};
const CONFIGS = {
  A:{},
  B:{reproCooldown:600, init:{...BASE_D.init, repro:[185,12]}, initEnergy:[130,175]},
  C:{reproCooldown:300, init:{...BASE_D.init, repro:[145,10]}},
  D:{vision:10, init:{...BASE_D.init, vision:[10,1.8], repro:[160,12]}},
  E:{vision:9, catchChance:.45, attackCooldown:160, init:{...BASE_D.init, vision:[9,1.6], repro:[160,12]}},
  F:{reproCooldown:520, attackCooldown:180, killBase:30, init:{...BASE_D.init, vision:[11,2], repro:[175,12]}, initEnergy:[120,165]},
  G:{reproCooldown:420, lifespan:[650,300], initCount:12, init:{...BASE_D.init, repro:[165,12]}},
  H:{reproCooldown:520, vision:10, attackCooldown:150, killBase:38, initCount:12, init:{...BASE_D.init, vision:[10,1.8], repro:[170,12]}, initEnergy:[120,170]},
};
function run(seed, cfg) {
  Object.assign(D, BASE_D);
  for (const [k,v] of Object.entries(cfg)) {
    if (k==='init') D.init = v; else D[k]=v;
  }
  const w = new SIM.World({seed, generations:240, mutation:8, regrowth:0.5, catastrophes:{
    drought:{interval:9999}, plague:{interval:9999}, bloom:{interval:9999}
  }});
  while (!w.done) w.step();
  const h = w.history;
  const since = 20;
  let pmin=1e9,pmax=0,dmin=1e9,dmax=0;
  for (let i=0;i<h.gen.length;i++) if (h.gen[i]>=since) {
    pmin=Math.min(pmin,h.prey[i]); pmax=Math.max(pmax,h.prey[i]);
    dmin=Math.min(dmin,h.predator[i]); dmax=Math.max(dmax,h.predator[i]);
  }
  return {seed, pmin,pmax,dmin,dmax, pf:h.prey.at(-1), df:h.predator.at(-1), fl:Math.round(h.flora.at(-1)),
    pSpd:h.traits.prey.speed.mean.at(-1)?.toFixed(2), dSpd:h.traits.predator.speed.mean.at(-1)?.toFixed(2),
    pVis:h.traits.prey.vision.mean.at(-1)?.toFixed(1), dVis:h.traits.predator.vision.mean.at(-1)?.toFixed(1), ext:w.prey.length===0||w.predators.length===0};
}
const seeds=[4407,1,2,99,7,123];
for (const [name,cfg] of Object.entries(CONFIGS)) {
  const rows=seeds.map(seed=>run(seed,cfg));
  const alive=rows.filter(r=>!r.ext).length;
  console.log(`\n${name}  alive ${alive}/${seeds.length}  cfg ${JSON.stringify(cfg).slice(0,80)}`);
  for (const r of rows) console.log(` seed ${String(r.seed).padStart(4)} prey ${r.pmin}-${r.pmax}→${r.pf} pred ${r.dmin}-${r.dmax}→${r.df} flora ${r.fl}% spd ${r.pSpd}/${r.dSpd} vis ${r.pVis}/${r.dVis}${r.ext?' EXTINCT':''}`);
}
EOF
