  A:{},
  B:{reproCooldown:600, init:{...BASE_D.init, repro:[185,12]}, initEnergy:[130,175]},
  C:{reproCooldown:300, init:{...BASE_D.init, repro:[145,10]}},
  D:{vision:10, init:{...BASE_D.init, vision:[10,1.8], repro:[160,12]}},
  E:{vision:9, catchChance:.45, attackCooldown:160, init:{...BASE_D.init, vision:[9,1.6], repro:[160,12]}},
  F:{reproCooldown:520, attackCooldown:180, killBase:30, init:{...BASE_D.init, vision:[11,2], repro:[175,12]}, initEnergy:[120,165]},
  G:{reproCooldown:420, lifespan:[650,300], initCount:12, init:{...BASE_D.init, repro:[165,12]}},
  H:{reproCooldown:520, vision:10, attackCooldown:150, killBase:38, initCount:12, init:{...BASE_D.init, vision:[10,1.8], repro:[170,12]}, initEnergy:[120,170]},
};
function run(seed, cfg) {
