  H:{reproCooldown:520, vision:10, attackCooldown:150, killBase:38, initCount:12, init:{...BASE_D.init, vision:[10,1.8], repro:[170,12]}, initEnergy:[120,170]},
  I:{reproCooldown:330, attackCooldown:100, catchChance:0.68, killBase:42, initCount:14, init:{...BASE_D.init, vision:[13,2], repro:[150,12]}, initEnergy:[120,165]},
  J:{reproCooldown:260, attackCooldown:95, catchChance:0.75, killBase:48, initCount:18, init:{...BASE_D.init, vision:[14,2], repro:[140,12]}, initEnergy:[120,165]},
};
function run(seed, cfg, events=false) {
  Object.assign(D, BASE_D);
  for (const [k,v] of Object.entries(cfg)) { if (k==='init') D.init = v; else D[k]=v; }
  const w = new SIM.World({seed, generations:300, mutation:8, regrowth:0.5, catastrophes: {
    drought:{interval:events?55:9999}, plague:{interval:events?85:9999}, bloom:{interval:events?115:9999}
  }});
  while (!w.done) w.step();
  const h = w.history;
  let pmin=1e9,pmax=0,dmin=1e9,dmax=0;
  for (let i=0;i<h.gen.length;i++) if (h.gen[i]>=20) {
    pmin=Math.min(pmin,h.prey[i]); pmax=Math.max(pmax,h.prey[i]);
    dmin=Math.min(dmin,h.predator[i]); dmax=Math.max(dmax,h.predator[i]);
  }
  return {seed, pmin,pmax,dmin,dmax, pf:h.prey.at(-1), df:h.predator.at(-1), fl:Math.round(h.flora.at(-1)),
    pSpd:h.traits.prey.speed.mean.at(-1)?.toFixed(2), dSpd:h.traits.predator.speed.mean.at(-1)?.toFixed(2),
    pVis:h.traits.prey.vision.mean.at(-1)?.toFixed(1), dVis:h.traits.predator.vision.mean.at(-1)?.toFixed(1),
    pMet:h.traits.prey.metabolism.mean.at(-1)?.toFixed(2), dMet:h.traits.predator.metabolism.mean.at(-1)?.toFixed(2),
    ext:w.prey.length===0||w.predators.length===0, plants:w.prey.length===0?'plantworld':''};
}
const seeds=[4407,1,2,99,7,123];
for (const ev of [false,true]) {
  console.log(`\n######## catastrophes ${ev?'ON':'OFF'}`);
  for (const [name,cfg] of Object.entries(CONFIGS)) {
    const rows=seeds.map(seed=>run(seed,cfg,ev));
    const alive=rows.filter(r=>!r.ext).length;
    console.log(`\n${name}  alive ${alive}/${seeds.length}`);
    for (const r of rows) console.log(` seed ${String(r.seed).padStart(4)} prey ${r.pmin}-${r.pmax}→${r.pf} pred ${r.dmin}-${r.dmax}→${r.df} flora ${r.fl}% spd ${r.pSpd}/${r.dSpd} vis ${r.pVis}/${r.dVis} met ${r.pMet}/${r.dMet}${r.ext?' EXTINCT':''}`);
  }
}
