```js
function headlessToHorizon() {
  if (state.finished) { openRecord(); return; }
  state.running = false; state.headless = true;
  const targetTicks = (world.target - world.gen) * TICKS_PER_GEN + (TICKS_PER_GEN - world.tickInGen);
  const started = performance.now();
  const work = () => {
    const t0 = performance.now();
    while (!world.done && performance.now() - t0 < 8) world.step();
    updateHeadlessProgress();
    if (!world.done) requestAnimationFrame(work);
    else { state.headless=false; finishRun('horizon', true); }
  };
  requestAnimationFrame(work);
}
```
