- Main loop:
```js
let lastFrame = performance.now();
let accumulator = 0;
function frame(now) {
  const dt = Math.min(100, now - lastFrame);
  lastFrame = now;
  if (state.headless) { /* no sim via loop */ }
  else if (state.running && !state.finished) {
    accumulator += dt / 1000 * BASE_TPS * state.speed;
    let n = 0;
    while (accumulator >= 1 && n < 40) { world.step(); accumulator -= 1; n++; if (world.done) break; }
    if (n === 40) accumulator = 0;
  }
  if (!recordOpen) drawWorld(now);
  drawDial(now);
  drawTimeline(now);
  updateLive(now);
  if (world.done && !state.finished) finishRun('horizon');
  requestAnimationFrame(frame);
}
```
