      <path d="M12.6 6.2A5 5 0 1 0 13 9.6M12.8 2.8v3.6H9.2" fill="none" stroke="currentColor" stroke-width="1.1" stroke-linecap="round" stroke-linejoin="round"/>
    </symbol>
    <symbol id="icon-pause" viewBox="0 0 16 16">
      <path d="M5.2 3.4h1.5v9.2H5.2zM9.3 3.4h1.5v9.2H9.3z"/>
    </symbol>
    <symbol id="icon-play" viewBox="0 0 16 16">
      <path d="m5 3.3 7.2 4.7L5 12.7z"/>
    </symbol>
    <symbol id="icon-step" viewBox="0 0 16 16">
      <path d="m3.6 3.5 6.3 4.5-6.3 4.5zM11 3.5h1.6v9H11z"/>
    </symbol>
    <symbol id="icon-recast" viewBox="0 0 16 16">
      <path d="M3 8a5 5 0 1 0 1.4-3.5M3 2.5v3.4h3.4" fill="none" stroke="currentColor" stroke-width="1.1" stroke-linecap="round" stroke-linejoin="round"/>
    </symbol>
    <symbol id="icon-seal" viewBox="0 0 16 16">
      <circle cx="8" cy="8" r="5.2" fill="none" stroke="currentColor" stroke-width="1"/>
      <path d="m5.7 8.1 1.5 1.5 3.1-3.4" fill="none" stroke="currentColor" stroke-width="1.1" stroke-linecap="round" stroke-linejoin="round"/>
    </symbol>
    <symbol id="icon-chevron" viewBox="0 0 16 16">
      <path d="m4 6 4 4 4-4" fill="none" stroke="currentColor" stroke-width="1.1" stroke-linecap="round" stroke-linejoin="round"/>
    </symbol>
    <symbol id="seal-ornament" viewBox="0 0 120 120">
      <circle cx="60" cy="60" r="55" fill="none" stroke="currentColor" stroke-width=".8"/>
      <circle cx="60" cy="60" r="49.5" fill="none" stroke="currentColor" stroke-width=".5" stroke-dasharray="1 4"/>
      <circle cx="60" cy="60" r="42" fill="none" stroke="currentColor" stroke-width=".5"/>
      <g fill="none" stroke="currentColor" stroke-width=".8">
        <path d="M60 34v31M60 48l-8-7M60 55l9-8"/>
        <path d="M42 73c7-4 13-4 18 0 5-4 11-4 18 0"/>
      </g>
      <text x="60" y="98" text-anchor="middle" font-family="'SFMono-Regular','SF Mono',Menlo,monospace" font-size="6.5" letter-spacing="2.2" fill="currentColor">OBSERVATION SEALED</text>
      <text x="60" y="45" text-anchor="middle" font-family="'Iowan Old Style',Palatino,Georgia,serif" font-size="17" font-style="italic" fill="currentColor">IV</text>
      <g fill="currentColor">
        <circle cx="60" cy="10" r="1"/><circle cx="60" cy="110" r="1"/>
        <circle cx="10" cy="60" r="1"/><circle cx="110" cy="60" r="1"/>
      </g>
    </symbol>
  </defs>
</svg>

<div class="folio" id="folio">
  <header class="masthead">
    <div class="brand">
      <div class="brand-seal" aria-hidden="true">
        <svg viewBox="0 0 52 52">
          <circle cx="26" cy="26" r="24" fill="none" stroke="currentColor" stroke-width=".7" opacity=".65"/>
          <circle cx="26" cy="26" r="20.5" fill="none" stroke="currentColor" stroke-width=".5" stroke-dasharray="1 3.6" opacity=".45"/>
          <g stroke="currentColor" stroke-width=".7" opacity=".55">
            <path d="M26 1.8v3M26 47.2v3M1.8 26h3M47.2 26h3"/>
          </g>
          <path d="M26 34.5V19M26 25l-5.5-4.2M26 28.5l5.7-4.4M26 20.5l-3.4-3" fill="none" stroke="#9cbb77" stroke-width=".9" stroke-linecap="round" opacity=".85"/>
          <text x="26" y="38.5" text-anchor="middle" font-family="'Iowan Old Style',Palatino,Georgia,serif" font-style="italic" font-size="7.5" fill="currentColor">IV</text>
        </svg>
      </div>
      <div class="brand-text">
        <h1 class="wordmark">Vivarium <span class="wordmark-no">No. IV</span></h1>
        <p class="subtitle">Field observations on appetite &amp; inheritance</p>
      </div>
    </div>
    <div class="masthead-meta">
      <div class="meta-item meta-spec">
        <span class="meta-label">Specimen</span>
        <span class="meta-value">Sealed glass · 128 × 80</span>
      </div>
      <div class="meta-item meta-state">
        <span class="meta-label">State</span>
        <span class="status" id="statusChip" data-state="live">
          <i class="status-dot" aria-hidden="true"></i>
          <span id="statusText">LIVE</span>
        </span>
      </div>
      <button type="button" class="drawer-toggle" id="drawerToggle" aria-expanded="true" aria-controls="instruments">
        <span>Instruments</span>
        <svg aria-hidden="true"><use href="#icon-sliders"/></svg>
      </button>
    </div>
  </header>
  <div class="top-rule" aria-hidden="true"></div>

  <main class="layout">
    <section class="stage" aria-label="The sealed vivarium">
      <div class="plate-head">
        <div class="plate-id">
          <h2 class="plate-title"><span class="num">IV</span>The glass</h2>
          <span class="plate-sub">128 × 80 field · 10,240 cells · sealed</span>
        </div>
        <div class="plate-state">
          <span class="condition" id="conditionLabel" data-event=""><i aria-hidden="true"></i><span id="conditionText">CLEAR</span></span>
          <div class="gen-read" aria-label="Generation">
            <span class="gen-caption">GEN</span>
            <span class="gen-now" id="genNow">000</span>
            <span class="gen-slash">/</span>
            <span class="gen-total" id="genTotal">240</span>
          </div>
        </div>
      </div>
      <div class="gen-track" aria-hidden="true"><span id="genFill"></span></div>

      <div class="plate-shell">
        <div class="plate" id="plate">
          <canvas id="worldCanvas" role="img" aria-label="A living field of lichen, moths and shrikes seen from above."></canvas>
          <div class="plate-glass" aria-hidden="true"></div>
          <div class="tint" id="tint" aria-hidden="true"></div>
          <div class="plate-marks" aria-hidden="true"><i></i><i></i><i></i><i></i></div>
          <div class="calamity" id="calamityBanner" aria-hidden="true">
            <span class="calamity-roman" id="calamityRoman">I</span>
            <span class="calamity-copy"><strong id="calamityName">Drought</strong><em id="calamityNote">the water table recedes</em></span>
            <span class="calamity-duration" id="calamityDuration">14 GEN</span>
          </div>
          <span class="glass-hint" id="glassHint">hover a living mark</span>
          <span class="held" id="heldStamp"><span id="heldText">held</span><i>under glass</i></span>
          <div class="specimen-tag" id="specimenTag" aria-hidden="true" hidden></div>
          <div class="headless-veil" id="headlessVeil" hidden>
            <div class="headless-inner">
              <span class="eyebrow">Without the glass</span>
              <p class="headless-title">Running the horizon</p>
              <div class="headless-track"><span id="headlessFill"></span></div>
              <div class="headless-meta"><span id="headlessCount">GEN 000 / 240</span><span>simulation only</span></div>
            </div>
          </div>
        </div>
      </div>

      <div class="caption-row">
        <div class="species-strip" aria-label="Living census">
          <div class="species" style="--sp: var(--plant)">
            <svg class="species-glyph" aria-hidden="true"><use href="#glyph-flora"/></svg>
            <span class="species-name">Flora <i>lichen</i></span>
            <span class="species-value"><b id="floraValue">—</b><em>% cover</em></span>
          </div>
          <div class="species" style="--sp: var(--prey)">
            <svg class="species-glyph" aria-hidden="true"><use href="#glyph-prey"/></svg>
            <span class="species-name">Prey <i>moths</i></span>
            <span class="species-value"><b id="preyValue">—</b><em>living</em></span>
          </div>
          <div class="species" style="--sp: var(--predator)">
            <svg class="species-glyph" aria-hidden="true"><use href="#glyph-predator"/></svg>
            <span class="species-name">Predator <i>shrikes</i></span>
            <span class="species-value"><b id="predatorValue">—</b><em>living</em></span>
          </div>
        </div>
        <div class="field-note">
          <span class="eyebrow">Field note <span class="line"></span></span>
          <p id="fieldNote">The slide is sealed. Something has already begun.</p>
        </div>
      </div>

      <div class="chronograph">
        <span class="chrono-edge">0</span>
        <div class="chrono-canvas-wrap"><canvas id="chronoCanvas" aria-hidden="true"></canvas></div>
        <span class="chrono-edge" id="chronoEnd">240</span>
      </div>
      <p class="sr-only" id="chronoSummary"></p>
    </section>

    <div class="drawer-slot" id="drawerSlot">
      <aside class="drawer" id="instruments" aria-label="Instruments of observation">
        <header class="drawer-head">
          <div class="eyebrow"><span>Instrumenta</span><span class="drawer-sub">live parameters</span></div>
          <button type="button" class="icon-btn" id="drawerClose" aria-label="Collapse instruments" data-tip="Collapse the instrument drawer. The glass keeps running." data-tip-title="Instruments">
            <svg aria-hidden="true"><use href="#icon-collapse"/></svg>
          </button>
        </header>

        <section class="dial-section" data-tip="A countdown instrument for the three scheduled disturbances. Each brass arc advances toward its next event; the centre shows whichever comes first or is active." data-tip-title="Calamity index">
          <div class="dial-head"><span>Calamity index</span><span class="dial-mode">automatic</span></div>
          <canvas id="dialCanvas" role="img" aria-label="Calamity countdown dial."></canvas>
          <div class="dial-foot"><span>Next <b id="dialNextShort">drought · 55</b></span><span>Armed <b id="armedCount">3 / 3</b></span></div>
        </section>

        <section class="panel-section" aria-labelledby="conditionsHeading">
          <div class="section-head"><span class="section-num">I</span><h3 id="conditionsHeading">Conditions</h3><span class="section-line"></span></div>

          <div class="field" data-tip="The origin of every random draw. The same seed and settings always produce the same world. Changing it recasts the slide from the beginning." data-tip-title="Seed">
            <div class="field-top">
              <label class="field-label" for="seedInput">Seed <span class="help-dot" aria-hidden="true">?</span></label>
              <canvas class="spark" id="sparkSeed" aria-hidden="true"></canvas>
            </div>
            <div class="seed-row">
              <input class="seed-input" id="seedInput" type="number" min="1" max="9999" step="1" value="4407" inputmode="numeric" autocomplete="off" spellcheck="false" aria-label="Seed value">
              <button type="button" class="square-btn" id="seedReroll" aria-label="Recast with a new seed">
                <svg aria-hidden="true"><use href="#icon-refresh"/></svg>
              </button>
            </div>
            <div class="seed-foot"><span>deterministic origin</span><span>1 – 9999</span></div>
          </div>

          <div class="field" data-tip="Gaussian drift applied to every inherited gene at birth. Higher values scatter the lineage; zero fixes it. Measured as a percentage of each gene's span." data-tip-title="Mutation rate">
            <div class="field-top">
              <label class="field-label" for="mutationRange">Mutation <span class="help-dot" aria-hidden="true">?</span></label>
              <canvas class="spark" id="sparkMutation" aria-hidden="true"></canvas>
              <output class="field-value" for="mutationRange"><b id="mutationValue">8.0</b><span class="unit">% / birth</span></output>
            </div>
            <input class="range" id="mutationRange" type="range" min="0" max="24" step="0.5" value="8">
            <div class="range-meta"><span>fixed inheritance</span><span class="mid" id="mutationNote">measured drift</span><span>volatile</span></div>
          </div>

          <div class="field" data-tip="How quickly grazed flora returns, expressed as a percentage of one cell per generation. This is the base of the food web: raise it and the meadow thickens; lower it and scarcity does the culling." data-tip-title="Food regrowth">
            <div class="field-top">
              <label class="field-label" for="regrowthRange">Regrowth <span class="help-dot" aria-hidden="true">?</span></label>
              <canvas class="spark" id="sparkRegrowth" aria-hidden="true"></canvas>
              <output class="field-value" for="regrowthRange"><b id="regrowthValue">6.0</b><span class="unit">% / gen</span></output>
            </div>
            <input class="range" id="regrowthRange" type="range" min="1" max="24" step="0.5" value="6">
            <div class="range-meta"><span>bare glass</span><span class="mid">flora</span><span>verdant</span></div>
          </div>

          <div class="field" data-tip="The number of generations this slide will be observed. Lower it to seal the record early; raise it to let inheritance run longer. Changes take effect immediately." data-tip-title="Horizon">
            <div class="field-top">
              <label class="field-label" for="horizonInput">Horizon <span class="help-dot" aria-hidden="true">?</span></label>
              <canvas class="spark" id="sparkHorizon" aria-hidden="true"></canvas>
            </div>
            <div class="stepper-row">
              <div class="stepper">
                <button type="button" class="step-btn" data-step="horizon" data-dir="-1" aria-label="Decrease horizon">−</button>
                <input class="step-input" id="horizonInput" type="number" min="40" max="2000" step="10" value="240" aria-label="Generations">
                <button type="button" class="step-btn" data-step="horizon" data-dir="1" aria-label="Increase horizon">+</button>
              </div>
              <span class="unit">generations</span>
              <span class="fill"></span>
              <span class="aside" id="horizonAside">ends at 240</span>
            </div>
          </div>

          <div class="field" data-tip="Simulation tempo, independent of drawing. Each generation is twelve ticks; the readout gives the resulting ticks per second. This knob never changes the outcome of a seeded run — only how quickly you witness it." data-tip-title="Tempo">
            <div class="field-top">
              <label class="field-label" for="tempoRange">Tempo <span class="help-dot" aria-hidden="true">?</span></label>
              <canvas class="spark" id="sparkTempo" aria-hidden="true"></canvas>
              <output class="field-value" for="tempoRange"><b id="tempoValue">2.0</b><span class="unit">× speed</span></output>
            </div>
            <input class="range" id="tempoRange" type="range" min="0" max="100" step="1" value="60">
            <div class="range-meta">
              <span>slow glass</span>
              <span class="mid" id="tempoNote">60 ticks / sec · ≈ 0:48</span>
              <span>swift</span>
            </div>
          </div>
        </section>

        <section class="panel-section" aria-labelledby="calamitiesHeading">
          <div class="section-head"><span class="section-num">II</span><h3 id="calamitiesHeading">Calamities</h3><span class="section-line"></span></div>

          <div class="calamity-item" data-type="drought" style="--ev-color: var(--drought)" data-tip="A scheduled dry spell: flora regrowth collapses to twelve percent for fourteen generations. Toggle the switch to leave drought out of the calendar." data-tip-title="Drought">
            <div class="calamity-top">
              <span class="calamity-numeral">I</span>
              <span class="calamity-name">Drought</span>
              <canvas class="spark calamity-spark" id="sparkDrought" aria-hidden="true"></canvas>
              <button type="button" class="switch" role="switch" aria-checked="true" data-toggle="drought" aria-label="Arm drought" data-tip="Arm or disarm drought. Disarming cancels future droughts; an active one runs its course." data-tip-title="Drought switch"></button>
            </div>
            <div class="calamity-bottom">
              <div class="stepper compact">
                <button type="button" class="step-btn" data-step="drought" data-dir="-1" aria-label="Decrease drought interval">−</button>
                <input class="step-input" id="droughtInput" type="number" min="15" max="400" step="5" value="55" aria-label="Drought interval in generations">
                <button type="button" class="step-btn" data-step="drought" data-dir="1" aria-label="Increase drought interval">+</button>
              </div>
              <span class="unit">gen</span>
              <span class="calamity-desc">regrowth ×0.12<br>withers 14 gen</span>
            </div>
          </div>

          <div class="calamity-item" data-type="plague" style="--ev-color: var(--plague)" data-tip="A fever in the moths: a portion of the prey are infected, weaken, and may spread the infection for twelve generations. The shrikes are spared. Toggle it out of the calendar if you wish." data-tip-title="Plague">
            <div class="calamity-top">
              <span class="calamity-numeral">II</span>
              <span class="calamity-name">Plague</span>
              <canvas class="spark calamity-spark" id="sparkPlague" aria-hidden="true"></canvas>
              <button type="button" class="switch" role="switch" aria-checked="true" data-toggle="plague" aria-label="Arm plague" data-tip="Arm or disarm plague. Disarming cancels future fevers; an active one runs its course." data-tip-title="Plague switch"></button>
            </div>
            <div class="calamity-bottom">
              <div class="stepper compact">
                <button type="button" class="step-btn" data-step="plague" data-dir="-1" aria-label="Decrease plague interval">−</button>
                <input class="step-input" id="plagueInput" type="number" min="15" max="400" step="5" value="85" aria-label="Plague interval in generations">
                <button type="button" class="step-btn" data-step="plague" data-dir="1" aria-label="Increase plague interval">+</button>
              </div>
              <span class="unit">gen</span>
              <span class="calamity-desc">fever in moths<br>lasts 12 gen</span>
            </div>
          </div>

          <div class="calamity-item" data-type="bloom" style="--ev-color: var(--bloom)" data-tip="A eutrophic bloom: flora surges, the glass greens, and sight shortens in the murk for sixteen generations. Not every disturbance is cruel — but all of them change the course of a lineage." data-tip-title="Bloom">
            <div class="calamity-top">
              <span class="calamity-numeral">III</span>
              <span class="calamity-name">Bloom</span>
              <canvas class="spark calamity-spark" id="sparkBloom" aria-hidden="true"></canvas>
              <button type="button" class="switch" role="switch" aria-checked="true" data-toggle="bloom" aria-label="Arm bloom" data-tip="Arm or disarm bloom. Disarming cancels future blooms; an active one runs its course." data-tip-title="Bloom switch"></button>
            </div>
            <div class="calamity-bottom">
              <div class="stepper compact">
                <button type="button" class="step-btn" data-step="bloom" data-dir="-1" aria-label="Decrease bloom interval">−</button>
                <input class="step-input" id="bloomInput" type="number" min="15" max="400" step="5" value="115" aria-label="Bloom interval in generations">
                <button type="button" class="step-btn" data-step="bloom" data-dir="1" aria-label="Increase bloom interval">+</button>
              </div>
              <span class="unit">gen</span>
              <span class="calamity-desc">sight ×0.56<br>lasts 16 gen</span>
            </div>
          </div>
        </section>

        <section class="panel-section" aria-labelledby="transportHeading">
          <div class="section-head"><span class="section-num">III</span><h3 id="transportHeading">Transport</h3><span class="section-line"></span></div>
          <div class="transport">
            <button type="button" class="btn primary" id="holdBtn" data-tip="Hold or resume the flow of time. While held, the world is frozen but its record is kept." data-tip-title="Hold">
              <svg id="holdIcon" aria-hidden="true"><use href="#icon-pause"/></svg><span id="holdLabel">Hold</span><span class="kbd">SPACE</span>
            </button>
            <button type="button" class="btn" id="stepBtn" data-tip="Advance exactly one generation while held. Each step is one twelfth of a full generation." data-tip-title="Step one generation">
              <svg aria-hidden="true"><use href="#icon-step"/></svg><span>Step</span>
            </button>
            <button type="button" class="btn" id="recastBtn" data-tip="Begin the same scenario again from generation zero. The seed is unchanged; the outcome is identical unless a parameter is moved." data-tip-title="Recast">
              <svg aria-hidden="true"><use href="#icon-recast"/></svg><span>Recast</span><span class="kbd">R</span>
            </button>
            <button type="button" class="btn" id="sealBtn" data-tip="Seal the slide now and open its record. All observations up to this generation are kept." data-tip-title="Seal the run">
              <svg aria-hidden="true"><use href="#icon-seal"/></svg><span id="sealLabel">Seal</span><span class="kbd">E</span>
            </button>
          </div>
          <div class="without-glass">
            <button type="button" class="link-btn" id="headlessBtn" data-tip="Compute the remaining generations with no drawing at all, then open the record. This is not a fast-forward through the glass; it is the simulation on its own." data-tip-title="Without the glass">
              <span>Run without the glass</span>
              <span class="kbd">H</span>
            </button>
            <p class="fineprint">simulation independent<br>of rendering</p>
          </div>
        </section>
      </aside>
    </div>
  </main>

  <footer class="colophon">
    <span>Vivarium No. IV <i>— an unbroken line from a single seed</i></span>
    <span class="shortcuts">
      <span><b>SPACE</b> hold</span>
      <span><b>R</b> recast</span>
      <span><b>N</b> new seed</span>
      <span><b>E</b> seal</span>
      <span><b>H</b> without glass</span>
    </span>
    <span class="colophon-seed">SEED <b id="footerSeed">4407</b> · GEN <b id="footerGen">000</b></span>
  </footer>
</div>

<button type="button" class="drawer-handle" id="drawerHandle" aria-label="Open instruments" aria-controls="instruments">Instruments</button>
<div class="drawer-scrim" id="drawerScrim" aria-hidden="true"></div>

<section class="record" id="record" role="dialog" aria-modal="true" aria-labelledby="recordTitle" hidden>
  <div class="record-inner">
    <header class="record-head">
      <div class="record-heading">
        <p class="eyebrow"><span class="roman">Plate V</span><span>·</span><span>The record</span></p>
        <h2 class="record-title" id="recordTitle" tabindex="-1">A sealed world, accounted for.</h2>
        <p class="record-deck" id="recordDeck">Seed 4407 · 240 generations</p>
      </div>
      <div class="record-head-right">
        <div class="seal-mark" aria-hidden="true">
          <svg viewBox="0 0 120 120"><use href="#seal-ornament"/></svg>
        </div>
        <div class="record-actions">
          <button type="button" class="btn" id="recordClose">View the glass</button>
          <button type="button" class="btn" id="recordReplay">Repeat the slide</button>
          <button type="button" class="btn primary" id="recordNew">New seed</button>
        </div>
      </div>
    </header>

    <div class="record-body">
      <aside class="record-aside">
        <div class="summary-block">
          <p class="eyebrow">The reckoning</p>
          <p class="outcome" id="outcomeText">Two lineages persist.</p>
          <dl class="ledger" id="recordLedger"></dl>
        </div>
        <div class="events-block">
          <h3 class="subhead">Disturbances weathered</h3>
          <ol class="event-list" id="recordEvents"></ol>
          <p class="empty-note" id="recordNoEvents" hidden>The calendar was left unarmed.</p>
          <h3 class="subhead">Notable drift</h3>
          <ul class="drift-list" id="recordDrift"></ul>
          <p class="aside-note" id="recordAsideNote">Every living mark on the final plate is descended from generation zero.</p>
        </div>
      </aside>

      <div class="record-charts">
        <section class="chart-section chart-frame chart-reveal" aria-labelledby="populationHeading">
          <div class="chart-head">
            <div>
              <h3 class="chart-h" id="populationHeading">Populations, observed</h3>
              <p class="chart-caption">Flora as percentage of cells covered (left). Living moths and shrikes as counts (right). Roman numerals mark the beginning of a disturbance.</p>
            </div>
            <div class="legend" aria-label="Chart legend">
              <span class="legend-item"><i class="legend-area" style="--lg: var(--plant)"></i>Flora</span>
              <span class="legend-item"><i class="legend-dash" style="--lg: var(--prey)"></i>Moths</span>
              <span class="legend-item"><i class="legend-dash" style="--lg: var(--predator)"></i>Shrikes</span>
            </div>
          </div>
          <canvas id="populationChart" role="img" aria-label="Population curves for flora, prey and predators over the recorded generations."></canvas>
        </section>

        <section class="traits-section" aria-labelledby="traitsHeading">
          <div class="traits-head">
            <div>
              <h3 class="chart-h" id="traitsHeading">Trait drift</h3>
