    <footer class="record-foot">
      <span>End of observation · <span id="recordEndReason">horizon reached</span></span>
      <span class="serif-note">“The glass offers no verdict; only the record.”</span>
      <span>128 × 80 cells · seed <span id="recordFooterSeed">4407</span> · vivarium No. IV</span>
    </footer>
    <span class="record-corner" aria-hidden="true"></span>
  </div>
</section>

<div class="tooltip" id="tooltip" role="tooltip" hidden>
  <span class="tt-title" id="tooltipTitle"></span>
  <span id="tooltipBody"></span>
