  }

  function showTooltip(el, x, y, keyboard) {
    if (!el || state.recordOpen) return;
    window.clearTimeout(state.tipHideTimer);
    if (state.tipEl !== el) state.tipEl = el;
    placeTooltip(el, x, y, keyboard);
  }

  function hideTooltip() {
    state.tipEl = null;
    els.tooltip.classList.remove('is-visible');
    window.clearTimeout(state.tipHideTimer);
    state.tipHideTimer = window.setTimeout(() => { els.tooltip.hidden = true; }, 170);
  }

  function bindTooltips() {
    document.addEventListener('pointerover', (e) => {
      if (e.pointerType === 'touch') return;
      const el = e.target.closest('[data-tip]');
      if (!el) return;
      showTooltip(el, e.clientX, e.clientY, false);
    });
    document.addEventListener('pointermove', (e) => {
      if (e.pointerType === 'touch' || !state.tipEl) return;
      const el = e.target.closest('[data-tip]');
      if (el === state.tipEl) placeTooltip(el, e.clientX, e.clientY, false);
    });
    document.addEventListener('pointerout', (e) => {
      if (e.pointerType === 'touch') return;
      const from = e.target.closest('[data-tip]');
      if (!from) return;
      const to = e.relatedTarget && e.relatedTarget.closest ? e.relatedTarget.closest('[data-tip]') : null;
      if (to === from) return;
      hideTooltip();
    });
    document.addEventListener('pointerdown', hideTooltip, true);
    document.addEventListener('focusin', (e) => {
      const el = e.target.closest('[data-tip]');
      if (!el) return;
      if (e.target.matches(':focus-visible')) {
        const r = e.target.getBoundingClientRect();
        showTooltip(el, r.left, r.bottom, true);
      }
    });
    document.addEventListener('focusout', (e) => {
      const el = e.target.closest('[data-tip]');
      if (!el) return;
      window.setTimeout(() => {
        const active = document.activeElement;
        if (!active || !active.closest || !active.closest('[data-tip]')) hideTooltip();
      }, 40);
    });
  }

  /* ---------------------------------------------------------------
     Sparklines — small instrument response curves
     --------------------------------------------------------------- */
  function prepareSpark(canvas) {
    if (!measureVisible(canvas)) return null;
    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    const rect = canvas.getBoundingClientRect();
    const w = Math.max(1, Math.round(rect.width));
    const h = Math.max(1, Math.round(rect.height));
    if (canvas.width !== Math.round(w * dpr) || canvas.height !== Math.round(h * dpr)) {
      canvas.width = Math.round(w * dpr);
      canvas.height = Math.round(h * dpr);
    }
    const ctx = canvas.getContext('2d');
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    ctx.clearRect(0, 0, w, h);
    return { ctx, w, h };
  }

  function sparkBase(ctx, w, h) {
    ctx.beginPath();
    ctx.strokeStyle = 'rgba(233,227,209,0.1)';
    ctx.lineWidth = 1;
    ctx.moveTo(0.5, h - 3.5);
    ctx.lineTo(w - 0.5, h - 3.5);
    ctx.stroke();
  }

  function sparkDot(ctx, x, y, color, radius = 1.6) {
    ctx.beginPath();
    ctx.fillStyle = color;
    ctx.arc(x, y, radius, 0, TAU);
    ctx.fill();
    ctx.beginPath();
    ctx.strokeStyle = hexA(color.startsWith('#') ? color : '#c7a15f', 0.28);
    ctx.arc(x, y, radius + 2.1, 0, TAU);
    ctx.stroke();
  }

  function drawSeedSpark() {
    const prep = prepareSpark(els.sparkSeed);
    if (!prep) return;
    const { ctx, w, h } = prep;
    const seed = world ? world.seed : clamp(Number(els.seedInput.value) || 4407, 1, 9999);
    let x = seed ^ 0x9e3779b9;
    const count = 25;
    const step = w / count;
    ctx.strokeStyle = 'rgba(231,207,152,0.4)';
    ctx.lineWidth = 1;
    for (let i = 0; i < count; i++) {
      x ^= x << 13; x ^= x >>> 17; x ^= x << 5;
      const v = ((x >>> 0) % 1000) / 1000;
      const bh = 2 + v * (h - 7);
      ctx.beginPath();
      ctx.moveTo(Math.round(i * step + step / 2) + 0.5, h - 3);
      ctx.lineTo(Math.round(i * step + step / 2) + 0.5, h - 3 - bh);
      ctx.stroke();
    }
    ctx.strokeStyle = 'rgba(233,227,209,0.11)';
    ctx.beginPath();
    ctx.moveTo(0.5, h - 2.5);
    ctx.lineTo(w - 0.5, h - 2.5);
    ctx.stroke();
  }

  function drawCurveSpark(canvas, opts) {
    const prep = prepareSpark(canvas);
    if (!prep) return;
    const { ctx, w, h } = prep;
    sparkBase(ctx, w, h);
    const { slope, color, current, curve, ticks } = opts;
    const padX = 2;
    const top = 3;
    const baseY = h - 4;
    const plotH = baseY - top;
    const fn = curve || ((x) => x);
    ctx.beginPath();
    for (let i = 0; i <= 40; i++) {
      const t = i / 40;
      const y = baseY - plotH * clamp(fn(t), 0, 1);
      const x = padX + t * (w - padX * 2);
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    }
    ctx.strokeStyle = color;
    ctx.lineWidth = 1;
    ctx.globalAlpha = 0.72;
    ctx.stroke();
    ctx.globalAlpha = 1;
    if (ticks) {
      ctx.strokeStyle = 'rgba(233,227,209,0.1)';
      for (let i = 1; i < 5; i++) {
        const x = padX + (i / 5) * (w - padX * 2);
        ctx.beginPath();
        ctx.moveTo(x, baseY + 1);
        ctx.lineTo(x, baseY + 3);
        ctx.stroke();
      }
    }
    const cx = padX + clamp(current, 0, 1) * (w - padX * 2);
    const cy = baseY - plotH * clamp(fn(clamp(current, 0, 1)), 0, 1);
    ctx.beginPath();
    ctx.strokeStyle = hexA(color, 0.22);
    ctx.setLineDash([1, 3]);
    ctx.moveTo(cx, cy + 2);
    ctx.lineTo(cx, baseY + 3);
    ctx.stroke();
    ctx.setLineDash([]);
    sparkDot(ctx, cx, cy, color);
    void slope;
  }

  function drawHorizonSpark() {
    const prep = prepareSpark(els.sparkHorizon);
    if (!prep) return;
    const { ctx, w, h } = prep;
    const target = clamp(Math.round(Number(els.horizonInput.value) || 240), 40, 2000);
    const per = target / 2000;
    const x = 2 + per * (w - 4);
    const y = h - 5;
    ctx.strokeStyle = 'rgba(233,227,209,0.12)';
    ctx.beginPath();
    ctx.moveTo(0.5, y + 0.5);
    ctx.lineTo(w - 0.5, y + 0.5);
    ctx.stroke();
    for (let i = 0; i <= 8; i++) {
      const tx = Math.round((i / 8) * (w - 1)) + 0.5;
      ctx.strokeStyle = i / 8 <= per ? 'rgba(199,161,95,0.62)' : 'rgba(233,227,209,0.14)';
      ctx.beginPath();
      ctx.moveTo(tx, y - (i % 2 === 0 ? 4 : 2));
      ctx.lineTo(tx, y + 1);
      ctx.stroke();
    }
    ctx.strokeStyle = 'rgba(199,161,95,0.6)';
    ctx.beginPath();
    ctx.moveTo(2, y + 0.5);
    ctx.lineTo(x, y + 0.5);
    ctx.stroke();
    sparkDot(ctx, x, y, '#c7a15f', 1.5);
  }

  function drawIntervalSpark(canvas, type) {
    const prep = prepareSpark(canvas);
    if (!prep) return;
    const { ctx, w, h } = prep;
    const def = EVENT_DEFS[type];
    const input = els[`${type}Input`];
    const interval = clamp(Math.round(Number(input.value) || def.defaultInterval), 15, 400);
    const target = world ? world.target : clamp(Number(els.horizonInput.value) || 240, 40, 2000);
    const enabled = document.querySelector(`[data-toggle="${type}"]`)?.getAttribute('aria-checked') === 'true';
    const color = def.color;
    sparkBase(ctx, w, h);
    const count = clamp(Math.floor(target / interval), 0, 18);
    const margin = 3;
    for (let i = 1; i <= count; i++) {
      const x = margin + (i / Math.max(count + 1, 1)) * (w - margin * 2);
      const bh = 3 + ((i * 7) % 6);
      ctx.strokeStyle = hexA(color, enabled ? 0.55 : 0.2);
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.moveTo(Math.round(x) + 0.5, h - 3);
      ctx.lineTo(Math.round(x) + 0.5, h - 3 - bh);
      ctx.stroke();
    }
    sparkDot(ctx, w - 3, h - 3.5, enabled ? color : '#5d6154', 1.35);
  }

  function drawSparks() {
    drawSeedSpark();
    const mutation = clamp(Number(els.mutationRange.value), 0, 24) / 24;
    drawCurveSpark(els.sparkMutation, {
      color: '#c7a15f',
      current: mutation,
      curve: (t) => 0.12 + 0.72 * (1 - Math.exp(-3.1 * t)),
    });
    const regrowth = (clamp(Number(els.regrowthRange.value), 1, 24) - 1) / 23;
    drawCurveSpark(els.sparkRegrowth, {
      color: '#9cbb77',
      current: regrowth,
      curve: (t) => 0.1 + 0.68 * (1 - Math.exp(-4.4 * t)),
    });
    drawHorizonSpark();
    const tempo = clamp(Number(els.tempoRange.value), 0, 100) / 100;
    drawCurveSpark(els.sparkTempo, {
      color: '#c7a15f',
      current: tempo,
      curve: (t) => 0.1 + 0.74 * t,
      ticks: true,
    });
    drawIntervalSpark(els.sparkDrought, 'drought');
    drawIntervalSpark(els.sparkPlague, 'plague');
    drawIntervalSpark(els.sparkBloom, 'bloom');
  }

  /* ---------------------------------------------------------------
     Simulation run lifecycle
     --------------------------------------------------------------- */
  function startNewRun() {
    window.clearTimeout(state.recordTimer);
    hideRecord(true);
    hideHover();
    const config = configFromControls();
    setControlValuesFromConfig(config);
    world = new SIM.World(config);
    state.running = true;
    state.finished = false;
    state.headless = false;
    state.startedAt = performance.now();
    state.elapsed = 0;
    state.accumulator = 0;
    state.lastFrame = performance.now();
    state.lastUI = 0;
    state.lastDial = 0;
    state.lastChrono = 0;
    state.activeKeys.clear();
    state.announced.clear();
    state.record = null;
    state.chartRefs = [];
    state.chartDrawn = false;
    state.lastNote = '';
    state.lastCondition = '';
    state.plantDirty = true;
    state.headlessStartedGen = 0;
    state.hoverAgent = null;
    state.hoverUid = null;
    els.headlessVeil.hidden = true;
    els.instruments.classList.remove('is-busy');
    els.calamityBanner.classList.remove('is-showing');
    window.clearTimeout(state.bannerTimer);
    els.tint.classList.remove('is-active');
    els.tint.style.background = 'transparent';
    els.plate.classList.remove('is-held');
    els.heldText.textContent = 'held';
    els.plate.dataset.event = '';
    for (const type of EVENT_ORDER) {
      document.querySelector(`.calamity-item[data-type="${type}"]`)?.classList.remove('is-active');
    }
    els.footerSeed.textContent = String(world.seed);
    els.genTotal.textContent = String(world.target);
    els.chronoEnd.textContent = String(world.target);
    els.horizonInput.value = String(world.target);
    els.seedInput.value = String(world.seed);
    els.recordFooterSeed.textContent = String(world.seed);
    makeMotes(world.seed);
    updateTransport();
    updateCondition();
    updateCounts();
    updateTimeNote();
    updateUI(performance.now(), true);
    drawWorld(performance.now());
    drawDial(performance.now());
    drawTimeline(performance.now());
    drawSparks();
    measureWorldCanvas();
    if (!REDUCED) {
      announce(world.gen === 0 ? `A new slide is sealed. Seed ${world.seed}. ${world.target} generations ahead.` : '');
    }
  }

  function pause() {
    if (state.finished || state.headless) return;
    state.running = false;
    state.accumulator = 0;
    updateTransport();
    announce('Observation held.');
  }

  function resume() {
    if (state.finished || state.headless) return;
    state.running = true;
    state.lastFrame = performance.now();
    state.accumulator = 0;
    updateTransport();
    announce('Observation resumed.');
  }

  function toggleHold() {
    if (state.finished) { openRecord(); return; }
    if (state.headless) return;
    if (state.running) pause(); else resume();
  }

  function stepGeneration() {
    if (state.finished || state.headless) return;
    if (state.running) {
      state.running = false;
      state.accumulator = 0;
    }
    const goal = world.gen + 1;
    let guard = GEN_TICKS * 2;
    while (world.gen < goal && !world.done && guard-- > 0) world.step();
    updateTransport();
    updateUI(performance.now(), true);
    drawWorld(performance.now());
    drawDial(performance.now());
    drawTimeline(performance.now());
    if (world.done) finishRun('horizon');
  }

  function finishRun(reason = 'horizon', shouldOpen = true) {
    if (!world || state.finished) return;
    if (reason === 'sealed' && !world.done) {
      world.done = true;
      world.finishReason = 'sealed';
    }
    state.finished = true;
    state.running = false;
    state.headless = false;
    state.elapsed = Math.max(0, (performance.now() - state.startedAt) / 1000);
    state.record = world.summary();
    state.accumulator = 0;
    els.headlessVeil.hidden = true;
    els.instruments.classList.remove('is-busy');
    els.plate.classList.add('is-held');
    els.heldText.textContent = 'sealed';
    updateTransport();
    updateUI(performance.now(), true);
    drawWorld(performance.now());
    drawDial(performance.now());
    drawTimeline(performance.now());
    if (shouldOpen) {
      window.clearTimeout(state.recordTimer);
      state.recordTimer = window.setTimeout(openRecord, REDUCED ? 120 : 780);
    }
    announce(`Observation sealed at generation ${world.gen}. The record is ready.`);
  }

  function sealOrRecord() {
    if (state.finished) openRecord();
    else finishRun('sealed', true);
  }

  /* ---------------------------------------------------------------
     Headless computation — the simulation without the glass
     --------------------------------------------------------------- */
  function runWithoutGlass() {
    if (!world || state.finished) { if (state.finished) openRecord(); return; }
    if (state.headless) return;
    if (state.running) state.running = false;
    state.headless = true;
    state.accumulator = 0;
    state.headlessStartedGen = world.gen;
    hideHover();
    els.headlessVeil.hidden = false;
    els.instruments.classList.add('is-busy');
    updateTransport();
    updateHeadlessVeil();
    announce('Running the horizon without the glass.');
    const pump = () => {
      if (!world || !state.headless) return;
      const start = performance.now();
      let ticks = 0;
      while (!world.done && performance.now() - start < 11) {
        world.step();
        ticks++;
      }
      updateHeadlessVeil();
      if (world.done) {
        els.headlessVeil.hidden = true;
        els.instruments.classList.remove('is-busy');
        state.headless = false;
        finishRun('horizon', true);
      } else {
        window.setTimeout(pump, 0);
      }
    };
    window.setTimeout(pump, 40);
  }

  function updateHeadlessVeil() {
    if (!world) return;
    const done = world.gen * GEN_TICKS + world.tickInGen;
    const total = Math.max(1, world.target * GEN_TICKS);
    const pct = clamp(done / total, 0, 1);
    els.headlessFill.style.width = `${(pct * 100).toFixed(2)}%`;
    els.headlessCount.textContent = `GEN ${pad(world.gen)} / ${world.target}`;
  }

  /* ---------------------------------------------------------------
     UI readouts & transport
     --------------------------------------------------------------- */
  function updateTransport() {
    const paused = !state.running && !state.finished && !state.headless;
    let label = 'LIVE';
    let dataState = 'live';
    if (state.headless) { label = 'COMPUTING'; dataState = 'held'; }
    else if (state.finished) { label = 'SEALED'; dataState = 'sealed'; }
    else if (paused) { label = 'HELD'; dataState = 'held'; }
    els.statusText.textContent = label;
    els.statusChip.dataset.state = dataState;
    els.holdBtn.disabled = state.finished || state.headless;
    els.stepBtn.disabled = state.finished || state.headless;
    els.headlessBtn.disabled = state.finished || state.headless;
    els.holdIcon.innerHTML = `<use href="${paused ? '#icon-play' : '#icon-pause'}"></use>`;
    els.holdLabel.textContent = paused ? 'Resume' : 'Hold';
    els.holdBtn.setAttribute('aria-pressed', String(paused));
    els.holdBtn.setAttribute('aria-label', paused ? 'Resume observation' : 'Hold observation');
    els.sealLabel.textContent = state.finished ? 'Record' : 'Seal';
    els.sealBtn.setAttribute('aria-label', state.finished ? 'Open the observation record' : 'Seal the slide and open its record');
    els.plate.classList.toggle('is-held', paused || state.finished || state.headless);
    els.heldText.textContent = state.finished ? 'sealed' : (state.headless ? 'without glass' : 'held');
    els.instruments.querySelectorAll('button, input').forEach((el) => {
      if (el.dataset.lockOnFinish !== 'false' && state.headless) el.disabled = true;
    });
    if (!state.headless) {
      // Re-enable controls that were disabled only for headless computation.
      els.instruments.querySelectorAll('button, input').forEach((el) => {
        if (el === els.holdBtn || el === els.stepBtn || el === els.headlessBtn) return;
        if (el.dataset.keepDisabled === 'true') return;
        el.disabled = false;
      });
    }
  }

  function updateCounts() {
    if (!world) return;
    const len = String(world.target).length;
    els.genNow.textContent = pad(world.gen, Math.max(3, len));
    els.genTotal.textContent = String(world.target);
    els.genFill.style.width = `${clamp((world.gen / Math.max(1, world.target)) * 100, 0, 100).toFixed(2)}%`;
    els.floraValue.textContent = String(Math.round(world.cover * 100));
    els.preyValue.textContent = fmt(world.prey.length);
    els.predatorValue.textContent = fmt(world.predators.length);
    els.footerGen.textContent = pad(world.gen, Math.max(3, len));
    els.footerSeed.textContent = String(world.seed);
    els.chronoEnd.textContent = String(world.target);
  }

  function updateCondition() {
    if (!world) return;
    const active = world.activeEvents;
    let text = 'CLEAR';
    let type = '';
    if (active.length) {
      const primary = active[active.length - 1];
      type = primary.type;
      text = EVENT_DEFS[primary.type].name.toUpperCase();
      if (active.length > 1) text += ` +${active.length - 1}`;
    }
    if (text !== state.lastCondition) {
      state.lastCondition = text;
      els.conditionText.textContent = text;
      els.conditionLabel.dataset.event = type;
      els.conditionLabel.setAttribute('aria-label', active.length ? `Current conditions: ${text.toLowerCase()}` : 'Conditions clear');
    } else if (els.conditionLabel.dataset.event !== type) {
      els.conditionLabel.dataset.event = type;
    }
  }

  function noteFor(worldRef) {
    const active = worldRef.activeEvents;
    if (active.length) {
      return EVENT_DEFS[active[active.length - 1].type].note + '.';
    }
    const prey = worldRef.prey.length;
    const pred = worldRef.predators.length;
    const flora = worldRef.cover * 100;
    if (worldRef.done) return 'The glass is sealed. The record has begun.';
    if (prey === 0 && pred === 0) return 'The glass is still. Nothing moves but the light.';
    if (prey === 0) return 'The moths are lost. The shrikes keep their watch over an empty meadow.';
    if (pred === 0) return 'No shrikes remain. The moths multiply in the quiet.';
    if (flora < 8) return 'Grazed to the quick; the glass shows through the green.';
    if (prey > 720) return 'The moths crowd the light. Every frond is spoken for.';
    if (pred > Math.max(3, prey * 0.2)) return 'The shrikes press close. The moths move in nervous arcs.';
    if (flora > 93) return 'The meadow is unbroken. The glass has gone green.';
    const quiet = [
      'A quiet generation. The glass keeps its counsel.',
      'Small inheritances gather at the grazing line.',
      'The shrikes quarter the field, patient as held breath.',
      'The moss closes behind the moths, unhurried.',
      'Nothing in the glass is still for long.',
    ];
    return quiet[Math.floor(worldRef.gen / 17) % quiet.length];
  }

  function updateFieldNote() {
    if (!world) return;
    const note = noteFor(world);
    if (note !== state.lastNote) {
      state.lastNote = note;
      els.fieldNote.textContent = note;
    }
  }

  function remainingSeconds() {
    if (!world) return 0;
    const left = Math.max(0, world.target - world.gen);
    return (left * GEN_TICKS - (left > 0 ? world.tickInGen : 0)) / (BASE_TPS * Math.max(0.01, state.speed));
  }

  function updateTimeNote() {
    if (!world) return;
    const ticksPerSec = Math.round(BASE_TPS * state.speed);
    let note;
    if (state.finished) note = `sealed · ${world.gen} generations`;
    else if (state.headless) note = `without glass · ${world.gen} / ${world.target}`;
    else note = `${ticksPerSec} ticks / sec · ≈ ${fmtTime(remainingSeconds())}`;
    els.tempoNote.textContent = note;
    els.horizonAside.textContent = state.finished ? `sealed at ${world.gen}` : `ends at ${world.target}`;
  }

  function updateUI(now, force = false) {
    if (!world) return;
    if (!force && now - state.lastUI < 92) return;
    state.lastUI = now;
    syncEvents();
    updateCounts();
    updateFieldNote();
    updateCondition();
    if (force || now - state.lastEstimate > 420) {
      state.lastEstimate = now;
      updateTimeNote();
      updateDialReadouts();
      updateHoverTagContent();
    }
    if (world.done && !state.finished) finishRun('horizon');
  }

  /* ---------------------------------------------------------------
     Event detection, banner, tint
     --------------------------------------------------------------- */
  function syncEvents() {
    if (!world) return;
    const current = new Map(world.activeEvents.map((e) => [`${e.type}:${e.start}`, e]));
    const started = [];
    const ended = [];
    for (const [key, ev] of current) if (!state.activeKeys.has(key)) started.push(ev);
    for (const key of state.activeKeys) if (!current.has(key)) ended.push(key.split(':')[0]);
    if (!started.length && !ended.length) return;

    for (const ev of started) {
      const def = EVENT_DEFS[ev.type];
      state.announced.add(`${ev.type}:${ev.start}`);
      announce(`Calamity ${def.num}: ${def.name}. ${def.note}. It lasts ${def.duration} generations.`);
    }
    if (ended.length && !started.length && !state.finished) {
      const names = ended.map((t) => EVENT_DEFS[t].name.toLowerCase()).join(' and ');
      announce(`The ${names} ${ended.length > 1 ? 'lift' : 'lifts'}.`);
    }
    if (started.length) {
      const ev = started[started.length - 1];
      showBanner(ev.type);
    }
    state.activeKeys = new Set(current.keys());
    for (const type of EVENT_ORDER) {
      const item = document.querySelector(`.calamity-item[data-type="${type}"]`);
      if (!item) continue;
      const active = [...current.values()].some((e) => e.type === type);
      item.classList.toggle('is-active', active);
    }
    updateTint([...current.values()]);
    updateCondition();
    updateDialReadouts();
    drawTimeline(performance.now());
    drawSparks();
    updateChronoSummary([...current.values()]);
  }

  function showBanner(type) {
    const def = EVENT_DEFS[type];
    els.calamityBanner.style.setProperty('--ev-color', def.color);
    els.calamityRoman.textContent = def.num;
    els.calamityName.textContent = def.name;
    els.calamityNote.textContent = def.note;
    els.calamityDuration.textContent = `${def.duration} GEN`;
    els.calamityBanner.classList.remove('is-showing');
    void els.calamityBanner.offsetWidth;
    els.calamityBanner.classList.add('is-showing');
    window.clearTimeout(state.bannerTimer);
    state.bannerTimer = window.setTimeout(() => {
      els.calamityBanner.classList.remove('is-showing');
    }, 4700);
  }

  function updateTint(activeEvents) {
    if (!activeEvents.length) {
      els.tint.classList.remove('is-active');
      els.plate.dataset.event = '';
      return;
    }
    const layers = activeEvents.map((ev, i) => {
      const c = EVENT_DEFS[ev.type].color;
      const x = 50 + (activeEvents.length > 1 ? (i - (activeEvents.length - 1) / 2) * 22 : 0);
      return `radial-gradient(115% 100% at ${x}% ${12 + i * 9}%, ${hexA(c, 0.16)}, transparent 66%)`;
    });
    els.tint.style.background = layers.join(', ');
    els.tint.classList.add('is-active');
    els.plate.dataset.event = activeEvents[activeEvents.length - 1].type;
  }

  function renderEventList() {
    const events = state.record ? state.record.events : [];
    els.recordEvents.innerHTML = '';
    events.forEach((ev) => {
      const li = document.createElement('li');
      li.style.setProperty('--ev', eventColor(ev.type));
      const sw = document.createElement('i');
      sw.className = 'event-swatch';
      const num = document.createElement('span');
      num.className = 'e-num';
      num.textContent = ev.num;
      const name = document.createElement('span');
      name.className = 'e-name';
      name.textContent = ev.name;
      const span = document.createElement('span');
      span.className = 'e-span';
      span.textContent = ev.open ? `${ev.start}–${ev.end}+` : `${ev.start}–${ev.end}`;
      li.append(sw, num, name, span);
      els.recordEvents.appendChild(li);
    });
    els.recordNoEvents.hidden = events.length > 0;
    els.recordEvents.hidden = events.length === 0;
  }

  function updateChronoSummary(active) {
    if (!world) return;
    const events = world.events;
    const parts = [`A ${world.target} generation observation.`];
    if (events.length) {
      parts.push(events.map((e) => `${e.name} from generation ${e.start} to ${e.end}`).join('; ') + '.');
    } else {
      parts.push('No disturbances have begun.');
    }
    if (active.length) parts.push(`Active: ${active.map((e) => e.name).join(', ')}.`);
    parts.push(`Generation ${world.gen}.`);
    els.chronoSummary.textContent = parts.join(' ');
  }

  function updateDialReadouts() {
    if (!world) return;
    let armed = 0;
    let next = null;
    for (const type of EVENT_ORDER) {
      const s = world.schedules[type];
      if (!s.armed) continue;
      armed++;
      if (!next || s.next < next.next) next = { type, next: s.next };
    }
    els.armedCount.textContent = `${armed} / 3`;
    if (world.activeEvents.length) {
      const active = world.activeEvents[world.activeEvents.length - 1];
      els.dialNextShort.textContent = `${EVENT_DEFS[active.type].name.toUpperCase()} · ACTIVE`;
    } else if (next) {
      els.dialNextShort.textContent = `${EVENT_DEFS[next.type].name.toUpperCase()} · ${Math.max(0, next.next - world.gen)}`;
    } else {
      els.dialNextShort.textContent = 'NONE ARMED';
    }
    els.dialCanvas.setAttribute(
      'aria-label',
      next || world.activeEvents.length
        ? `Calamity dial. ${world.activeEvents.length ? `Active: ${world.activeEvents.map((e) => e.name).join(', ')}.` : `Next: ${EVENT_DEFS[next.type].name} in ${Math.max(0, next.next - world.gen)} generations.`}`
        : 'Calamity dial. No disturbances are armed.'
    );
  }

  /* ---------------------------------------------------------------
     Loop
     --------------------------------------------------------------- */
  function loop(now) {
    if (!state.lastFrame) state.lastFrame = now;
    const dt = Math.min(100, Math.max(0, now - state.lastFrame));
    state.lastFrame = now;

    if (world && state.running && !state.finished && !state.headless) {
      state.accumulator += (dt / 1000) * BASE_TPS * state.speed;
      let steps = 0;
      while (state.accumulator >= 1 && steps < 40) {
        world.step();
        state.accumulator -= 1;
        steps++;
        if (world.done) break;
      }
      if (steps >= 40) state.accumulator = 0;
      if (world.done && !state.finished) {
        finishRun('horizon');
      }
    }

    if (!state.recordOpen) {
      drawWorld(now);
      if (now - state.lastDial > 32) {
        drawDial(now);
        state.lastDial = now;
      }
      if (now - state.lastChrono > 150) {
        drawTimeline(now);
        state.lastChrono = now;
      }
    }
    updateUI(now);
    raf = requestAnimationFrame(loop);
  }

  /* ---------------------------------------------------------------
     World rendering
     --------------------------------------------------------------- */
  function worldSize() {
    const c = els.worldCanvas;
    const cssW = Math.max(1, Math.round(c.clientWidth));
    const cssH = Math.max(1, Math.round(c.clientHeight));
    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    if (c.width !== Math.round(cssW * dpr) || c.height !== Math.round(cssH * dpr)) {
      c.width = Math.round(cssW * dpr);
      c.height = Math.round(cssH * dpr);
      state.plantDirty = true;
    }
    const cell = Math.min(cssW / SIM.W, cssH / SIM.H);
    view.w = cssW;
    view.h = cssH;
    view.dpr = dpr;
    view.cell = cell;
    view.ox = (cssW - SIM.W * cell) / 2;
    view.oy = (cssH - SIM.H * cell) / 2;
  }

  function measureWorldCanvas() {
    worldSize();
  }

  function makeMotes(seed) {
    const rng = new SIM.Random((seed ^ 0x51ed270b) >>> 0);
    state.motes = Array.from({ length: 30 }, () => ({
      x: rng.next(),
      y: rng.next(),
      phase: rng.next() * TAU,
      drift: 0.006 + rng.next() * 0.02,
      size: 0.5 + rng.next() * 1.3,
      tilt: 0.3 + rng.next() * 0.7,
    }));
  }

  function initPlantLayer() {
    const off = document.createElement('canvas');
    off.width = SIM.W;
    off.height = SIM.H;
    const ctx = off.getContext('2d');
    const img = ctx.createImageData(SIM.W, SIM.H);
    plantLayer = { canvas: off, ctx, img, paletteKey: '' };
    state.plantDirty = true;
  }

  function buildPalette(eventType) {
    // A 256-entry moss → pale lichen ramp.
    const high = eventType === 'drought'
      ? [142, 121, 79]
      : eventType === 'bloom'
        ? [143, 211, 170]
        : [170, 197, 136];
    const low = eventType === 'drought'
      ? [48, 44, 30]
      : eventType === 'bloom'
        ? [38, 77, 65]
        : [54, 73, 47];
    const table = new Uint8ClampedArray(256 * 4);
    for (let i = 0; i < 256; i++) {
      const t = i / 255;
      table[i * 4] = low[0] + (high[0] - low[0]) * t;
      table[i * 4 + 1] = low[1] + (high[1] - low[1]) * t;
      table[i * 4 + 2] = low[2] + (high[2] - low[2]) * t;
      table[i * 4 + 3] = 12 + t * 165;
    }
    return table;
  }

  function refreshPlantLayer() {
    if (!plantLayer || !world) return;
    const active = world.activeEvents;
    const evKey = active.length ? active[active.length - 1].type : 'clear';
    if (plantLayer.paletteKey !== evKey) {
      plantLayer.lut = buildPalette(evKey);
      plantLayer.paletteKey = evKey;
      state.plantDirty = true;
    }
    if (!state.plantDirty) return;
    const data = plantLayer.img.data;
    const plants = world.plants;
    const lut = plantLayer.lut;
    for (let i = 0; i < SIM.CELLS; i++) {
      const idx = (clamp(plants[i], 0, 1) * 255) | 0;
      const k = i * 4;
      const l = idx * 4;
      data[k] = lut[l];
      data[k + 1] = lut[l + 1];
      data[k + 2] = lut[l + 2];
      data[k + 3] = lut[l + 3];
    }
    plantLayer.ctx.putImageData(plantLayer.img, 0, 0);
    state.plantDirty = false;
  }

  function cellScreen(x, y) {
    return {
      x: view.ox + x * view.cell + view.cell / 2,
      y: view.oy + y * view.cell + view.cell / 2,
    };
  }

  function drawWorld(now) {
    if (!world) return;
    worldSize();
    const c = els.worldCanvas;
    const ctx = c.getContext('2d');
    ctx.setTransform(view.dpr, 0, 0, view.dpr, 0, 0);
    const w = view.w;
    const h = view.h;
    ctx.clearRect(0, 0, w, h);
    ctx.fillStyle = '#070a08';
    ctx.fillRect(0, 0, w, h);

    const bg = ctx.createRadialGradient(w * 0.5, h * 0.44, 0, w * 0.5, h * 0.5, Math.max(w, h) * 0.72);
    bg.addColorStop(0, 'rgba(50, 64, 48, 0.28)');
    bg.addColorStop(0.6, 'rgba(25, 34, 27, 0.1)');
    bg.addColorStop(1, 'rgba(3, 5, 4, 0)');
    ctx.fillStyle = bg;
    ctx.fillRect(0, 0, w, h);

    // Engraved registration grid, every eight cells.
    ctx.beginPath();
    ctx.strokeStyle = 'rgba(228, 220, 196, 0.042)';
    ctx.lineWidth = 1;
    for (let x = 8; x < SIM.W; x += 8) {
      const sx = Math.round(view.ox + x * view.cell) + 0.5;
      ctx.moveTo(sx, view.oy);
      ctx.lineTo(sx, view.oy + SIM.H * view.cell);
    }
    for (let y = 8; y < SIM.H; y += 8) {
      const sy = Math.round(view.oy + y * view.cell) + 0.5;
      ctx.moveTo(view.ox, sy);
      ctx.lineTo(view.ox + SIM.W * view.cell, sy);
    }
    ctx.stroke();

    // Cell-edge ticks.
    ctx.strokeStyle = 'rgba(199, 161, 95, 0.14)';
    ctx.beginPath();
    for (let x = 0; x <= SIM.W; x += 8) {
      const sx = Math.round(view.ox + x * view.cell) + 0.5;
      ctx.moveTo(sx, view.oy);
      ctx.lineTo(sx, view.oy + 3);
      ctx.moveTo(sx, view.oy + SIM.H * view.cell);
      ctx.lineTo(sx, view.oy + SIM.H * view.cell - 3);
    }
    for (let y = 0; y <= SIM.H; y += 8) {
      const sy = Math.round(view.oy + y * view.cell) + 0.5;
      ctx.moveTo(view.ox, sy);
      ctx.lineTo(view.ox + 3, sy);
      ctx.moveTo(view.ox + SIM.W * view.cell, sy);
      ctx.lineTo(view.ox + SIM.W * view.cell - 3, sy);
    }
    ctx.stroke();

    refreshPlantLayer();
    if (plantLayer) {
      ctx.save();
      ctx.imageSmoothingEnabled = true;
      ctx.imageSmoothingQuality = 'high';
      ctx.drawImage(plantLayer.canvas, view.ox, view.oy, SIM.W * view.cell, SIM.H * view.cell);
      ctx.restore();
    }

    // Stipple and frond marks make the soft plant layer feel engraved.
    const plantMarks = ctx;
    plantMarks.save();
    plantMarks.beginPath();
    plantMarks.fillStyle = 'rgba(182, 205, 148, 0.32)';
    for (let i = 0; i < SIM.CELLS; i++) {
      const b = world.plants[i];
      if (b < 0.3) continue;
      const hsh = ((i * 2654435761) >>> 0) % 97;
      if (hsh > 22) continue;
      const x = i % SIM.W;
      const y = (i / SIM.W) | 0;
      const jx = (((i * 1103515245 + 12345) >>> 0) % 100) / 100 - 0.5;
      const jy = (((i * 22695477 + 1) >>> 0) % 100) / 100 - 0.5;
      const px = view.ox + (x + 0.5 + jx * 0.7) * view.cell;
      const py = view.oy + (y + 0.5 + jy * 0.7) * view.cell;
      const s = 0.7 + b * 1.5;
      plantMarks.rect(px, py, s, s);
    }
    plantMarks.fill();
    plantMarks.beginPath();
    plantMarks.strokeStyle = 'rgba(208, 224, 174, 0.24)';
    plantMarks.lineWidth = 0.8;
    for (let i = 0; i < SIM.CELLS; i++) {
      const b = world.plants[i];
      if (b < 0.68) continue;
      const hsh = ((i * 1597334677) >>> 0) % 131;
      if (hsh > 16) continue;
      const x = i % SIM.W;
      const y = (i / SIM.W) | 0;
      const px = view.ox + (x + 0.5) * view.cell;
      const py = view.oy + (y + 0.5) * view.cell;
      const s = Math.max(1.1, view.cell * 0.22);
      plantMarks.moveTo(px, py + s);
      plantMarks.lineTo(px, py - s);
      plantMarks.moveTo(px, py);
      plantMarks.lineTo(px - s * 0.8, py - s * 0.45);
      plantMarks.moveTo(px, py + s * 0.2);
      plantMarks.lineTo(px + s * 0.9, py - s * 0.35);
    }
    plantMarks.stroke();
    plantMarks.restore();

    // Ambient motes under the living marks.
    if (!REDUCED) drawMotes(ctx, now);

    // Trails first, then bodies.
    drawPrey(ctx);
    drawPredators(ctx);

    if (state.hoverAgent && !state.hoverAgent.dead) {
      drawHoverRing(ctx, state.hoverAgent);
    } else if (state.hoverAgent && state.hoverAgent.dead) {
      hideHover();
    }
  }

  function drawMotes(ctx, now) {
    const t = now * 0.001;
    const active = world.activeEvents;
    const ev = active.length ? active[active.length - 1].type : null;
    const color = ev === 'drought' ? '208, 161, 95' : ev === 'plague' ? '169, 155, 196' : ev === 'bloom' ? '111, 186, 163' : '233, 227, 209';
    for (const m of state.motes) {
      let x;
      let y;
      if (ev === 'drought') {
        x = ((m.x + t * m.drift * 0.32) % 1 + 1) % 1;
        y = ((m.y + t * m.drift * 1.2) % 1 + 1) % 1;
      } else if (ev === 'plague') {
        x = ((m.x + Math.sin(t * m.drift * 5 + m.phase) * 0.012) % 1 + 1) % 1;
        y = ((m.y - t * m.drift * 0.3) % 1 + 1) % 1;
      } else if (ev === 'bloom') {
        x = ((m.x + Math.sin(t * m.drift * 2.2 + m.phase) * 0.02) % 1 + 1) % 1;
        y = ((m.y + t * m.drift * 0.18) % 1 + 1) % 1;
      } else {
        x = ((m.x + Math.sin(t * 0.02 * m.tilt + m.phase) * 0.012) % 1 + 1) % 1;
        y = ((m.y + t * 0.004 * m.tilt) % 1 + 1) % 1;
      }
      const px = view.ox + x * SIM.W * view.cell;
      const py = view.oy + y * SIM.H * view.cell;
      ctx.beginPath();
      ctx.fillStyle = `rgba(${color}, ${0.08 + m.size * 0.045})`;
      ctx.arc(px, py, m.size * 0.8, 0, TAU);
      ctx.fill();
    }
  }

  function agentScreen(a) {
    return {
      x: view.ox + a.x * view.cell,
      y: view.oy + a.y * view.cell,
    };
  }

  function drawPrey(ctx) {
    const color = '#e2bd7b';
    const halo = new Path2D();
    const bodies = new Path2D();
    const heads = new Path2D();
    const infected = [];
    const list = world.prey;
    const scale = Math.max(1.2, view.cell * 0.31);
    ctx.lineCap = 'round';
    for (let i = 0; i < list.length; i++) {
      const a = list[i];
      const s = agentScreen(a);
      const size = scale * (0.78 + clamp(a.energy / 75, 0, 1) * 0.38);
      const dx = Math.cos(a.dir);
      const dy = Math.sin(a.dir);
      halo.moveTo(s.x + size * 2.6, s.y);
      halo.arc(s.x, s.y, size * 2.6, 0, TAU);
      const tipX = s.x + dx * size * 1.25;
      const tipY = s.y + dy * size * 1.25;
      const backX = s.x - dx * size * 0.9;
      const backY = s.y - dy * size * 0.9;
      const px = -dy * size * 0.9;
      const py = dx * size * 0.9;
      bodies.moveTo(tipX, tipY);
      bodies.quadraticCurveTo(s.x + px, s.y + py, backX, backY);
      bodies.quadraticCurveTo(s.x - px, s.y - py, tipX, tipY);
      heads.moveTo(tipX + 0.7, tipY);
      heads.arc(tipX, tipY, Math.max(0.55, size * 0.22), 0, TAU);
      if (a.infected) infected.push(s);
    }
    ctx.fillStyle = 'rgba(226,189,123,0.045)';
    ctx.fill(halo);
    ctx.strokeStyle = 'rgba(226,189,123,0.78)';
    ctx.lineWidth = Math.max(0.85, Math.min(1.2, view.cell * 0.055));
    ctx.stroke(bodies);
    ctx.fillStyle = 'rgba(245, 219, 165, 0.88)';
    ctx.fill(heads);
    if (infected.length) {
      ctx.strokeStyle = 'rgba(169,155,196,0.7)';
      ctx.lineWidth = 0.9;
      ctx.setLineDash([1.5, 2.2]);
      for (const p of infected) {
        ctx.beginPath();
        ctx.arc(p.x, p.y, scale * 3.1, 0, TAU);
        ctx.stroke();
      }
      ctx.setLineDash([]);
    }
  }

  function drawPredators(ctx) {
    const color = '#d7745d';
    const bodies = new Path2D();
    const halo = new Path2D();
    const tips = new Path2D();
    const list = world.predators;
    const scale = Math.max(1.6, view.cell * 0.4);
    for (let i = 0; i < list.length; i++) {
      const a = list[i];
      const s = agentScreen(a);
      const size = scale * (0.84 + clamp(a.energy / 180, 0, 1) * 0.32);
      const dx = Math.cos(a.dir);
      const dy = Math.sin(a.dir);
      const px = -dy;
      const py = dx;
      halo.moveTo(s.x + size * 2.2, s.y);
      halo.arc(s.x, s.y, size * 2.2, 0, TAU);
      bodies.moveTo(s.x + dx * size * 1.55, s.y + dy * size * 1.55);
      bodies.lineTo(s.x - dx * size * 0.65 + px * size * 0.92, s.y - dy * size * 0.65 + py * size * 0.92);
      bodies.lineTo(s.x + dx * size * 0.1, s.y + dy * size * 0.1);
      bodies.lineTo(s.x - dx * size * 0.65 - px * size * 0.92, s.y - dy * size * 0.65 - py * size * 0.92);
      bodies.closePath();
      tips.moveTo(s.x + dx * size * 1.55 + 0.9, s.y + dy * size * 1.55);
      tips.arc(s.x + dx * size * 1.55, s.y + dy * size * 1.55, Math.max(0.6, size * 0.23), 0, TAU);
    }
    ctx.fillStyle = 'rgba(215,116,93,0.05)';
    ctx.fill(halo);
    ctx.fillStyle = 'rgba(215,116,93,0.92)';
    ctx.fill(bodies);
    ctx.fillStyle = 'rgba(247, 203, 177, 0.92)';
    ctx.fill(tips);
  }

  function drawHoverRing(ctx, a) {
    const s = agentScreen(a);
    const sight = a.genes.vision * view.cell;
    const color = a.species === 'prey' ? '#e2bd7b' : '#d7745d';
    ctx.save();
    ctx.beginPath();
    ctx.rect(view.ox, view.oy, SIM.W * view.cell, SIM.H * view.cell);
    ctx.clip();
    ctx.setLineDash([2.2, 4.2]);
    ctx.strokeStyle = hexA(color, 0.42);
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.arc(s.x, s.y, Math.max(8, sight), 0, TAU);
    ctx.stroke();
    ctx.setLineDash([]);
    ctx.strokeStyle = hexA(color, 0.8);
    ctx.beginPath();
    ctx.arc(s.x, s.y, Math.max(5.5, sight * 0.12), 0, TAU);
    ctx.stroke();
    ctx.restore();
  }

  /* ---------------------------------------------------------------
     Hover specimen card
     --------------------------------------------------------------- */
  function findNearestAgent(px, py) {
    const threshold = 17;
    let best = null;
    let bestD = threshold * threshold;
    for (const species of ['prey', 'predator']) {
      const list = species === 'prey' ? world.prey : world.predators;
      for (const a of list) {
        const s = agentScreen(a);
        const dx = s.x - px;
        const dy = s.y - py;
        const d = dx * dx + dy * dy;
        if (d < bestD) { bestD = d; best = a; }
      }
    }
    return best;
  }

  function updateHoverSelection() {
    if (!world || !state.pointerInside || state.recordOpen || state.headless) {
      if (!state.pointerInside) hideHover();
      return;
    }
    if (state.hoverAgent) {
      if (state.hoverAgent.dead) hideHover();
      else {
        const s = agentScreen(state.hoverAgent);
        const dx = s.x - state.pointerX;
        const dy = s.y - state.pointerY;
        if (dx * dx + dy * dy < 25 * 25) return;
      }
    }
    const found = findNearestAgent(state.pointerX, state.pointerY);
    if (found) {
      const changed = state.hoverUid !== found.uid;
      state.hoverAgent = found;
      state.hoverUid = found.uid;
      els.plate.classList.add('has-hover');
      els.specimenTag.hidden = false;
      if (changed) updateHoverTagContent(true);
    } else {
      hideHover();
    }
  }

  function hideHover() {
    state.hoverAgent = null;
    state.hoverUid = null;
    state.pointerInside = false;
    els.specimenTag.hidden = true;
    els.plate.classList.remove('has-hover');
  }

  function updateHoverTagContent(force = false) {
    if (!state.hoverAgent || state.hoverAgent.dead) return;
    const now = performance.now();
    if (!force && now - state.hoverUpdated < 220) return;
    state.hoverUpdated = now;
    const a = state.hoverAgent;
    const speciesName = a.species === 'prey' ? 'Moth' : 'Shrike';
    const role = a.species === 'prey' ? 'prey' : 'predator';
    const color = a.species === 'prey' ? '#e2bd7b' : '#d7745d';
    const status = a.infected ? 'INFECTED' : a.energy >= a.genes.repro ? 'FERTILE' : a.species === 'prey' ? 'FORAGING' : 'QUARTERING';
    const geneRow = (g) => {
      const gene = geneById(g);
      return `<span class="tag-gene">${gene.short}<b>${geneValue(gene, a.genes[g])}</b></span>`;
    };
    const energyMax = Math.max(a.genes.repro, 1);
    const energyPct = clamp(a.energy / (energyMax * 1.3), 0, 1) * 100;
    els.specimenTag.style.setProperty('--tag-color', color);
    els.specimenTag.innerHTML = `
      <div class="tag-head">
        <svg class="tag-glyph" aria-hidden="true"><use href="#${a.species === 'prey' ? 'glyph-prey' : 'glyph-predator'}"/></svg>
        <span class="tag-name"><b>${speciesName}</b> · ${role}</span>
        <span class="tag-id">NO. ${String(a.uid).padStart(4, '0')}</span>
      </div>
      <div class="tag-genes">
        ${geneRow('speed')}
        ${geneRow('vision')}
        ${geneRow('metabolism')}
        ${geneRow('repro')}
      </div>
      <div class="tag-foot"><span>ENERGY <b>${Math.round(a.energy)}</b> / ${Math.round(a.genes.repro)}</span><span>AGE <b>${Math.floor(a.age / GEN_TICKS)}</b> gen</span></div>
      <div class="tag-energy"><i style="width:${energyPct.toFixed(1)}%"></i></div>
      <div class="tag-foot"><span>${String(a.x.toFixed(0)).padStart(2, '0')} · ${String(a.y.toFixed(0)).padStart(2, '0')}</span><span class="tag-status">${status}</span></div>`;
  }

  function positionHoverTag() {
    if (!state.hoverAgent || state.hoverAgent.dead || els.specimenTag.hidden) return;
    const a = state.hoverAgent;
    const s = agentScreen(a);
    const tagW = els.specimenTag.offsetWidth || 214;
    const tagH = els.specimenTag.offsetHeight || 132;
    const margin = 10;
    let left = s.x + 18;
    if (left + tagW > view.w - margin) left = s.x - tagW - 18;
    left = clamp(left, margin, view.w - tagW - margin);
    let top = s.y - tagH * 0.48;
    top = clamp(top, margin, view.h - tagH - margin);
    els.specimenTag.style.left = `${Math.round(left)}px`;
    els.specimenTag.style.top = `${Math.round(top)}px`;
  }

  /* ---------------------------------------------------------------
     Dial canvas
     --------------------------------------------------------------- */
  function prepareCanvas(canvas) {
    const rect = canvas.getBoundingClientRect();
    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    const w = Math.max(1, Math.round(rect.width));
    const h = Math.max(1, Math.round(rect.height));
    if (canvas.width !== Math.round(w * dpr) || canvas.height !== Math.round(h * dpr)) {
      canvas.width = Math.round(w * dpr);
      canvas.height = Math.round(h * dpr);
    }
    const ctx = canvas.getContext('2d');
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    ctx.clearRect(0, 0, w, h);
    return { ctx, w, h, dpr };
  }

  function drawDial(now) {
    if (!world) return;
    const prep = prepareCanvas(els.dialCanvas);
    if (!prep) return;
    const { ctx, w, h } = prep;
    const cx = w / 2;
    const cy = h / 2 + 5;
    const R = Math.min(w * 0.37, h * 0.42);
    const start = (135 * Math.PI) / 180;
    const sweep = (270 * Math.PI) / 180;
    const genFloat = world.gen + world.tickInGen / GEN_TICKS;

    ctx.save();
    ctx.strokeStyle = 'rgba(233,227,209,0.14)';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.arc(cx, cy, R + 4, 0, TAU);
    ctx.stroke();
    ctx.strokeStyle = 'rgba(199,161,95,0.2)';
    ctx.beginPath();
    ctx.arc(cx, cy, R + 1, 0, TAU);
    ctx.stroke();

    // Graduations around the bezel
    for (let i = 0; i <= 60; i++) {
      const a = start + (i / 60) * sweep;
      const long = i % 5 === 0;
      const r1 = R + 1.5;
      const r2 = R + (long ? 6.5 : 4);
      ctx.strokeStyle = long ? 'rgba(199,161,95,0.48)' : 'rgba(233,227,209,0.16)';
      ctx.beginPath();
      ctx.moveTo(cx + Math.cos(a) * r1, cy + Math.sin(a) * r1);
      ctx.lineTo(cx + Math.cos(a) * r2, cy + Math.sin(a) * r2);
      ctx.stroke();
    }

    // Three concentric event arcs
    const types = EVENT_ORDER;
    const radii = [R - 17, R - 30, R - 43];
    for (let i = 0; i < types.length; i++) {
      const type = types[i];
      const def = EVENT_DEFS[type];
      const s = world.schedules[type];
      const radius = radii[i];
      ctx.beginPath();
      ctx.strokeStyle = 'rgba(233,227,209,0.09)';
      ctx.lineWidth = 1;
      ctx.arc(cx, cy, radius, start, start + sweep);
      ctx.stroke();
      if (!s.armed) {
        ctx.beginPath();
        ctx.strokeStyle = hexA(def.color, 0.18);
        ctx.setLineDash([1, 4]);
        ctx.arc(cx, cy, radius, start, start + sweep);
        ctx.stroke();
        ctx.setLineDash([]);
      } else {
        const active = world.activeEvents.find((e) => e.type === type);
        let progress;
        if (active) progress = 1;
        else progress = clamp(1 - (s.next - genFloat) / Math.max(1, s.interval), 0, 1);
        ctx.beginPath();
        ctx.strokeStyle = hexA(def.color, active ? 0.95 : 0.68);
        ctx.lineWidth = active ? 2.2 : 1.7;
        ctx.arc(cx, cy, radius, start, start + sweep * progress);
        ctx.stroke();
        const head = start + sweep * progress;
        const hx = cx + Math.cos(head) * radius;
        const hy = cy + Math.sin(head) * radius;
        ctx.beginPath();
        ctx.fillStyle = active ? def.color : hexA(def.color, 0.85);
        ctx.arc(hx, hy, active ? 2.8 : 2.1, 0, TAU);
        ctx.fill();
        if (active) {
          ctx.beginPath();
          ctx.strokeStyle = hexA(def.color, 0.35);
          ctx.lineWidth = 1;
          ctx.arc(hx, hy, 5.5, 0, TAU);
          ctx.stroke();
        }
      }
      // label at start of each arc
      ctx.font = '7px "SFMono-Regular", "SF Mono", Menlo, monospace';
      ctx.fillStyle = s.armed ? hexA(def.color, 0.8) : 'rgba(233,227,209,0.22)';
      ctx.textAlign = 'right';
      ctx.textBaseline = 'middle';
      const lx = cx + Math.cos(start) * (radius - 8);
      const ly = cy + Math.sin(start) * (radius - 8);
      ctx.fillText(def.num, lx, ly);
    }

    // Center crosshair registration
    ctx.strokeStyle = 'rgba(233,227,209,0.09)';
    ctx.beginPath();
    ctx.moveTo(cx - 3, cy + R * 0.61);
    ctx.lineTo(cx + 3, cy + R * 0.61);
    ctx.moveTo(cx, cy + R * 0.61 - 3);
    ctx.lineTo(cx, cy + R * 0.61 + 3);
    const active = world.activeEvents[world.activeEvents.length - 1];
    if (active) {
      const def = EVENT_DEFS[active.type];
      ctx.strokeStyle = 'rgba(169,155,196,0.1)';
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.moveTo(cx, cy); 
      ctx.stroke();
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillStyle = hexA(def.color, 0.86);
      ctx.font = '6.5px "SFMono-Regular", "SF Mono", Menlo, monospace';
      ctx.fillText('IN PROGRESS', cx, cy - 22);
      ctx.fillStyle = '#e9e3d1';
      ctx.font = 'italic 17px "Iowan Old Style", Georgia, serif';
      ctx.fillText(def.name, cx, cy - 6);
      ctx.fillStyle = 'rgba(233,227,209,0.58)';
      ctx.font = '7px "SFMono-Regular", "SF Mono", Menlo, monospace';
      ctx.fillText(`${Math.max(0, active.end - world.gen)} GEN REMAIN`, cx, cy + 12);
    } else {
      let next = null;
      for (const type of EVENT_ORDER) {
        const s = world.schedules[type];
        if (s.armed && (!next || s.next < next.next)) next = { type, next: s.next };
      }
      if (next) {
        const def = EVENT_DEFS[next.type];
        const remaining = Math.max(0, next.next - world.gen);
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillStyle = 'rgba(233,227,209,0.34)';
        ctx.font = '6px "SFMono-Regular", "SF Mono", Menlo, monospace';
        ctx.fillText('NEXT', cx, cy - 31);
        ctx.fillStyle = hexA(def.color, 0.85);
        ctx.font = 'italic 16px "Iowan Old Style", Georgia, serif';
        ctx.fillText(def.name, cx, cy - 16);
        ctx.fillStyle = '#e9e3d1';
        ctx.font = '26px "Iowan Old Style", Georgia, serif';
        ctx.fillText(String(remaining), cx, cy + 9);
        ctx.fillStyle = 'rgba(233,227,209,0.34)';
        ctx.font = '6px "SFMono-Regular", "SF Mono", Menlo, monospace';
        ctx.fillText('GENERATIONS', cx, cy + 28);
      } else {
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillStyle = 'rgba(233,227,209,0.34)';
        ctx.font = '6px "SFMono-Regular", "SF Mono", Menlo, monospace';
        ctx.fillText('NO CALAMITIES', cx, cy - 5);
        ctx.fillText('ARMED', cx, cy + 5);
      }
    }
    ctx.restore();
    void now;
  }

  /* ---------------------------------------------------------------
     Chronograph canvas
     --------------------------------------------------------------- */
  function drawTimeline(now) {
    if (!world) return;
    const prep = prepareCanvas(els.chronoCanvas);
    if (!prep) return;
    const { ctx, w, h } = prep;
    const pad = 3;
    const y = 10.5;
    const usable = w - pad * 2;
    const maxGen = Math.max(1, world.target);
    const genX = (gen) => pad + (gen / maxGen) * usable;
    ctx.strokeStyle = 'rgba(233,227,209,0.11)';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(pad, y + 0.5);
    ctx.lineTo(w - pad, y + 0.5);
    ctx.stroke();

    const tickStep = niceTickStep(maxGen);
    ctx.strokeStyle = 'rgba(233,227,209,0.075)';
    ctx.beginPath();
    for (let g = 0; g <= maxGen; g += tickStep) {
      const x = Math.round(genX(g)) + 0.5;
      ctx.moveTo(x, y - 1);
      ctx.lineTo(x, y + 2);
    }
    ctx.stroke();

    // Event durations as quiet bands
    for (const ev of world.events) {
      const def = EVENT_DEFS[ev.type];
      const x1 = genX(ev.start);
      const x2 = genX(Math.min(ev.end, world.gen));
      ctx.fillStyle = hexA(def.color, 0.2);
      ctx.fillRect(x1, y + 3, Math.max(1, x2 - x1), 3);
      ctx.fillStyle = hexA(def.color, 0.74);
      ctx.beginPath();
      const mx = x1;
      ctx.moveTo(mx, y - 3);
      ctx.lineTo(mx + 2.3, y);
      ctx.lineTo(mx, y + 3);
      ctx.lineTo(mx - 2.3, y);
      ctx.closePath();
      ctx.fill();
    }

    // Forecast diamonds
    for (const type of EVENT_ORDER) {
      const s = world.schedules[type];
      if (!s.armed || s.next > maxGen) continue;
      const x = genX(s.next);
      ctx.strokeStyle = hexA(EVENT_DEFS[type].color, 0.36);
      ctx.beginPath();
      ctx.moveTo(x, y - 2.7);
      ctx.lineTo(x + 2.1, y);
      ctx.lineTo(x, y + 2.7);
      ctx.lineTo(x - 2.1, y);
      ctx.closePath();
      ctx.stroke();
    }

    // Progress
    const px = genX(world.gen);
    ctx.fillStyle = 'rgba(199,161,95,0.5)';
    ctx.fillRect(pad, y + 0.5, Math.max(0, px - pad), 1);
    ctx.fillStyle = world.done ? '#e7cf98' : '#e9e3d1';
    ctx.beginPath();
    ctx.arc(px, y + 0.5, world.done ? 2.4 : 1.8, 0, TAU);
    ctx.fill();
    if (!world.done) {
      ctx.strokeStyle = 'rgba(233,227,209,0.2)';
      ctx.beginPath();
      ctx.arc(px, y + 0.5, 4.4, 0, TAU);
      ctx.stroke();
    }
    void now;
  }

  function niceTickStep(max) {
    const rough = max / 10;
    const mag = Math.pow(10, Math.floor(Math.log10(Math.max(1, rough))));
    const norm = rough / mag;
    let step;
    if (norm < 1.5) step = 1;
    else if (norm < 3) step = 2;
    else if (norm < 7) step = 5;
    else step = 10;
    return Math.max(1, step * mag);
  }

  /* ---------------------------------------------------------------
     Charts in the record
     --------------------------------------------------------------- */
  function drawPopulationChart() {
    if (!state.record) return;
    const prep = prepareCanvas(els.populationChart);
    if (!prep) return;
    const { ctx, w, h } = prep;
    const data = state.record.history;
    if (!data.gen.length) return;
    const padL = 38;
    const padR = 38;
    const padT = 26;
    const padB = 27;
    const plotW = Math.max(1, w - padL - padR);
    const plotH = Math.max(1, h - padT - padB);
    const lastGen = Math.max(1, data.gen[data.gen.length - 1]);
    const maxAnimal = Math.max(10, data.preyPeak || 0, data.predatorPeak || 0);
    const animalTop = niceMax(maxAnimal * 1.06);
    const x = (g) => padL + (g / lastGen) * plotW;
    const yAnimal = (v) => padT + plotH * (1 - clamp(v / animalTop, 0, 1));
    const yPlant = (v) => padT + plotH * (1 - clamp(v / 100, 0, 1));
    const mono = (size) => `${size}px "SFMono-Regular", "SF Mono", Menlo, monospace`;
    const serif = (size, italic = false) => `${italic ? 'italic ' : ''}${size}px "Iowan Old Style", "Palatino Linotype", Palatino, Georgia, serif`;

    // Event fields
    for (const ev of state.record.events) {
      if (ev.start > lastGen) continue;
      const def = EVENT_DEFS[ev.type];
      const x1 = x(ev.start);
      const x2 = x(Math.min(ev.end, lastGen));
      ctx.fillStyle = hexA(def.color, 0.055);
      ctx.fillRect(x1, padT, Math.max(1, x2 - x1), plotH);
      ctx.strokeStyle = hexA(def.color, 0.18);
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.moveTo(Math.round(x1) + 0.5, padT);
      ctx.lineTo(Math.round(x1) + 0.5, padT + plotH);
      ctx.stroke();
    }

    // Grid
    const grid = [0, 0.5, 1];
    ctx.font = mono(7);
    ctx.textBaseline = 'middle';
    grid.forEach((f) => {
      const yy = padT + plotH * f;
      ctx.strokeStyle = f === 1 ? 'rgba(233,227,209,0.16)' : 'rgba(233,227,209,0.07)';
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.moveTo(padL, Math.round(yy) + 0.5);
      ctx.lineTo(padL + plotW, Math.round(yy) + 0.5);
      ctx.stroke();
      ctx.textAlign = 'right';
      ctx.fillStyle = 'rgba(156,187,119,0.62)';
      ctx.fillText(String(Math.round(100 * (1 - f))), padL - 8, yy);
      ctx.textAlign = 'left';
      ctx.fillStyle = 'rgba(233,227,209,0.33)';
      ctx.fillText(fmt(animalTop * (1 - f)), padL + plotW + 8, yy);
    });
    // Quarter lines
    ctx.strokeStyle = 'rgba(233,227,209,0.035)';
    for (const f of [0.25, 0.75]) {
      const yy = Math.round(padT + plotH * f) + 0.5;
      ctx.beginPath();
      ctx.moveTo(padL, yy);
      ctx.lineTo(padL + plotW, yy);
      ctx.stroke();
    }

    // X axis labels
    ctx.font = mono(7);
    ctx.fillStyle = 'rgba(233,227,209,0.34)';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'top';
    for (let i = 0; i <= 4; i++) {
      const g = Math.round((lastGen * i) / 4);
      ctx.fillText(String(g), x(g), padT + plotH + 8);
    }
    ctx.textAlign = 'right';
    ctx.fillStyle = 'rgba(233,227,209,0.26)';
    ctx.fillText('GENERATIONS', padL + plotW, padT + plotH + 19);
    ctx.textAlign = 'left';
    ctx.fillStyle = 'rgba(156,187,119,0.65)';
    ctx.fillText('FLORA %', padL, padT - 14);
    ctx.textAlign = 'right';
    ctx.fillStyle = 'rgba(233,227,209,0.34)';
    ctx.fillText('ANIMALS · COUNT', padL + plotW, padT - 14);

    // Flora area
    ctx.save();
    ctx.beginPath();
    ctx.rect(padL, padT, plotW, plotH);
    ctx.clip();
    ctx.beginPath();
    let first = true;
    for (let i = 0; i < data.gen.length; i++) {
      const xx = x(data.gen[i]);
      const yy = yPlant(data.flora[i]);
      if (first) { ctx.moveTo(xx, yy); first = false; } else ctx.lineTo(xx, yy);
    }
    ctx.lineTo(x(data.gen[data.gen.length - 1]), padT + plotH);
    ctx.lineTo(x(data.gen[0]), padT + plotH);
    ctx.closePath();
    const grad = ctx.createLinearGradient(0, padT, 0, padT + plotH);
    grad.addColorStop(0, 'rgba(156,187,119,0.2)');
    grad.addColorStop(1, 'rgba(156,187,119,0.015)');
    ctx.fillStyle = grad;
    ctx.fill();
    ctx.beginPath();
    first = true;
    for (let i = 0; i < data.gen.length; i++) {
      const xx = x(data.gen[i]);
      const yy = yPlant(data.flora[i]);
      if (first) { ctx.moveTo(xx, yy); first = false; } else ctx.lineTo(xx, yy);
    }
    ctx.strokeStyle = 'rgba(156,187,119,0.64)';
    ctx.lineWidth = 1.1;
    ctx.stroke();

    // Animal lines
    const lines = [
      { key: 'prey', color: '#e2bd7b' },
      { key: 'predator', color: '#d7745d' },
    ];
    for (const line of lines) {
      ctx.beginPath();
      let started = false;
      for (let i = 0; i < data.gen.length; i++) {
        const val = data[line.key][i];
        const xx = x(data.gen[i]);
        const yy = yAnimal(val);
        if (!started) { ctx.moveTo(xx, yy); started = true; } else ctx.lineTo(xx, yy);
      }
      ctx.strokeStyle = line.color;
      ctx.lineWidth = 1.45;
      ctx.globalAlpha = 0.92;
      ctx.stroke();
      ctx.globalAlpha = 1;
      const last = data[line.key][data[line.key].length - 1];
      ctx.beginPath();
      ctx.fillStyle = line.color;
      ctx.arc(x(lastGen), yAnimal(last), 2.2, 0, TAU);
      ctx.fill();
    }
    ctx.restore();

    // Event markers and labels above the plot
    let lastLabelX = -100;
    const labelRow = 0;
    for (const ev of state.record.events) {
      if (ev.start > lastGen) continue;
      const def = EVENT_DEFS[ev.type];
      const xx = x(ev.start);
      ctx.fillStyle = hexA(def.color, 0.8);
      ctx.beginPath();
      ctx.moveTo(xx, 8);
      ctx.lineTo(xx + 2.8, 10.8);
      ctx.lineTo(xx, 13.6);
      ctx.lineTo(xx - 2.8, 10.8);
      ctx.closePath();
      ctx.fill();
      if (xx - lastLabelX > 14) {
        ctx.font = mono(6.5);
        ctx.textAlign = 'left';
        ctx.textBaseline = 'top';
        ctx.fillStyle = hexA(def.color, 0.72);
        ctx.fillText(ev.num, xx + 4, 4 + labelRow);
        lastLabelX = xx;
      }
    }

    // Extinctions annotation
    const findLoss = (key) => {
      let seen = false;
      for (let i = 0; i < data.gen.length; i++) {
        if (data[key][i] > 0) seen = true;
        else if (seen) return data.gen[i];
      }
      return null;
    };
    const preyLoss = findLoss('prey');
    const predatorLoss = findLoss('predator');
    ctx.font = mono(7);
    ctx.textAlign = 'left';
    ctx.textBaseline = 'bottom';
    if (preyLoss !== null) {
      ctx.fillStyle = 'rgba(226,189,123,0.58)';
      ctx.fillText(`MOTHS LOST · GEN ${preyLoss}`, padL + 4, padT + plotH - 5);
    }
    if (predatorLoss !== null) {
      ctx.fillStyle = 'rgba(215,116,93,0.65)';
      ctx.fillText(`SHRIKES LOST · GEN ${predatorLoss}`, padL + 4, padT + plotH - (preyLoss !== null ? 15 : 5));
    }

    els.populationChart.setAttribute(
      'aria-label',
      `Population curves. Flora ends at ${Math.round(data.flora[data.flora.length - 1])} percent cover. Moths end at ${data.prey[data.prey.length - 1]}, peak ${data.preyPeak}. Shrikes end at ${data.predator[data.predator.length - 1]}, peak ${data.predatorPeak}.`
    );
  }

  function niceMax(v) {
    if (v <= 10) return 10;
    const mag = Math.pow(10, Math.floor(Math.log10(v)));
    const norm = v / mag;
    let mult = 1;
    if (norm <= 1) mult = 1;
    else if (norm <= 2) mult = 2;
    else if (norm <= 2.5) mult = 2.5;
    else if (norm <= 5) mult = 5;
    else mult = 10;
    return Math.ceil(mult * mag);
  }

  function buildTraitRows() {
    if (!state.record) return;
    els.traitRows.innerHTML = '';
    state.chartRefs = [];
    const rec = state.record;
    const species = [
      { key: 'prey', label: 'Moths', sub: 'prey', color: '#e2bd7b', count: rec.counts.prey },
      { key: 'predator', label: 'Shrikes', sub: 'predators', color: '#d7745d', count: rec.counts.predator },
    ];
    species.forEach((sp, si) => {
      if (sp.count === 0) sp.sub = `${sp.sub} · lost`;
      const row = document.createElement('div');
      row.className = 'trait-row';
      row.style.setProperty('--sp', sp.color);
      const label = document.createElement('div');
      label.className = 'trait-row-label';
      label.innerHTML = `${sp.label}<span>${sp.sub}</span>`;
      const grid = document.createElement('div');
      grid.className = 'trait-grid';
      GENE_DEFS.forEach((gene, gi) => {
        const store = rec.history.traits[sp.key][gene.key];
        const startMean = store.mean.find((v) => v !== null);
        const endMean = [...store.mean].reverse().find((v) => v !== null);
        const endSd = [...store.sd].reverse().find((v) => v !== null);
        const tile = document.createElement('figure');
        tile.className = 'trait-tile chart-reveal';
        tile.style.setProperty('--sp', sp.color);
        tile.style.animationDelay = `${0.06 + (si * 4 + gi) * 0.045}s`;
        const caption = document.createElement('figcaption');
        caption.className = 'trait-tile-head';
        caption.innerHTML = `<span class="trait-tile-name">${gene.name}</span><span class="trait-tile-unit">${gene.unit}</span>`;
        const canvas = document.createElement('canvas');
        canvas.className = 'trait-canvas';
        canvas.setAttribute('role', 'img');
        canvas.setAttribute(
          'aria-label',
          `${sp.label} ${gene.name} mean and spread. Start ${startMean === null ? 'none' : geneValue(gene, startMean)}, end ${endMean === null ? 'none' : geneValue(gene, endMean)}.`
        );
        const foot = document.createElement('div');
        foot.className = 'trait-foot';
        foot.innerHTML = `<span>${startMean === null ? '—' : geneValue(gene, startMean)} → <b>${endMean === null ? '—' : geneValue(gene, endMean)}</b></span><span class="delta">± ${endSd === null || endSd === undefined ? '—' : geneValue(gene, endSd)}</span>`;
        tile.append(caption, canvas, foot);
        grid.appendChild(tile);
        state.chartRefs.push({ canvas, species: sp.key, gene });
      });
      row.append(label, grid);
      els.traitRows.appendChild(row);
    });
  }

  function drawTraitCharts() {
    if (!state.record) return;
    const rec = state.record;
    const lastGen = Math.max(1, rec.history.gen[rec.history.gen.length - 1]);
    for (const ref of state.chartRefs) {
      const prep = prepareCanvas(ref.canvas);
      if (!prep) continue;
      const { ctx, w, h } = prep;
      const data = rec.history.traits[ref.species][ref.gene.key];
      const gene = ref.gene;
      const color = ref.species === 'prey' ? '#e2bd7b' : '#d7745d';
      const padL = 25;
      const padR = 6;
      const padT = 8;
      const padB = 14;
      const plotW = Math.max(1, w - padL - padR);
      const plotH = Math.max(1, h - padT - padB);
      let yMin = Infinity;
      let yMax = -Infinity;
      for (let i = 0; i < data.mean.length; i++) {
        if (data.mean[i] === null) continue;
        yMin = Math.min(yMin, data.mean[i] - data.sd[i]);
        yMax = Math.max(yMax, data.mean[i] + data.sd[i]);
      }
      if (!Number.isFinite(yMin) || !Number.isFinite(yMax)) {
        ctx.fillStyle = 'rgba(233,227,209,0.3)';
        ctx.font = '7px "SFMono-Regular", Menlo, monospace';
        ctx.textAlign = 'center';
        ctx.fillText('NO LIVING SUBJECTS', w / 2, h / 2);
        continue;
      }
      const span = yMax - yMin;
      const padY = span * 0.15 || 0.1;
      yMin -= padY;
      yMax += padY;
      const x = (g) => padL + (g / lastGen) * plotW;
      const y = (v) => padT + plotH * (1 - (v - yMin) / (yMax - yMin));
      const mono = (size) => `${size}px "SFMono-Regular", "SF Mono", Menlo, monospace`;

      // event lines
      for (const ev of rec.events) {
        if (ev.start > lastGen) continue;
        ctx.strokeStyle = hexA(EVENT_DEFS[ev.type].color, 0.12);
        ctx.lineWidth = 1;
        ctx.beginPath();
        ctx.moveTo(Math.round(x(ev.start)) + 0.5, padT);
        ctx.lineTo(Math.round(x(ev.start)) + 0.5, padT + plotH);
        ctx.stroke();
      }
      // grid
      ctx.strokeStyle = 'rgba(233,227,209,0.065)';
      ctx.lineWidth = 1;
      for (const f of [0, 0.5, 1]) {
        const yy = Math.round(padT + plotH * f) + 0.5;
        ctx.beginPath();
        ctx.moveTo(padL, yy);
        ctx.lineTo(padL + plotW, yy);
        ctx.stroke();
      }
      // labels
      ctx.font = mono(6.3);
      ctx.textBaseline = 'middle';
      ctx.fillStyle = 'rgba(233,227,209,0.28)';
      ctx.textAlign = 'right';
      ctx.fillText(geneValue(gene, yMax), padL - 4, padT + 1);
      ctx.fillText(geneValue(gene, yMin), padL - 4, padT + plotH - 1);
      ctx.textBaseline = 'top';
      ctx.textAlign = 'left';
      ctx.fillStyle = 'rgba(233,227,209,0.24)';
      ctx.fillText('0', padL, padT + plotH + 4);
      ctx.textAlign = 'right';
      ctx.fillText(String(lastGen), padL + plotW, padT + plotH + 4);

      ctx.save();
      ctx.beginPath();
      ctx.rect(padL, padT, plotW, plotH);
      ctx.clip();
      // spread
      ctx.beginPath();
      let first = true;
      for (let i = 0; i < data.mean.length; i++) {
        if (data.mean[i] === null) continue;
        const xx = x(rec.history.gen[i]);
        const yy = y(data.mean[i] + data.sd[i]);
        if (first) { ctx.moveTo(xx, yy); first = false; } else ctx.lineTo(xx, yy);
      }
      for (let i = data.mean.length - 1; i >= 0; i--) {
        if (data.mean[i] === null) continue;
        ctx.lineTo(x(rec.history.gen[i]), y(data.mean[i] - data.sd[i]));
      }
      ctx.closePath();
      ctx.fillStyle = hexA(color, 0.11);
      ctx.fill();

      // mean line: break across nulls
      ctx.beginPath();
      let drawing = false;
      for (let i = 0; i < data.mean.length; i++) {
        if (data.mean[i] === null) { drawing = false; continue; }
        const xx = x(rec.history.gen[i]);
        const yy = y(data.mean[i]);
        if (!drawing) { ctx.moveTo(xx, yy); drawing = true; } else ctx.lineTo(xx, yy);
      }
      ctx.strokeStyle = color;
      ctx.globalAlpha = 0.92;
      ctx.lineWidth = 1.2;
      ctx.stroke();
      ctx.globalAlpha = 1;

      const lastIdx = data.mean.length - 1;
      let endIdx = lastIdx;
      while (endIdx >= 0 && data.mean[endIdx] === null) endIdx--;
      if (endIdx >= 0) {
        ctx.beginPath();
        ctx.fillStyle = color;
        ctx.arc(x(rec.history.gen[endIdx]), y(data.mean[endIdx]), 2, 0, TAU);
        ctx.fill();
        ctx.beginPath();
        ctx.strokeStyle = hexA(color, 0.25);
        ctx.arc(x(rec.history.gen[endIdx]), y(data.mean[endIdx]), 3.6, 0, TAU);
        ctx.stroke();
      }
      ctx.restore();
    }
  }

  function drawCharts() {
    if (!state.record) return;
    drawPopulationChart();
    drawTraitCharts();
    state.chartDrawn = true;
  }

  /* ---------------------------------------------------------------
     Record assembly
     --------------------------------------------------------------- */
  function buildRecord() {
    if (!state.record) return;
    const rec = state.record;
    const target = rec.target;
    const endGen = rec.gen;
    const events = rec.events;
    const finishReason = rec.done ? (rec.finishReason || 'horizon') : rec.finishReason;
    els.recordDeck.textContent = `Seed ${rec.seed} · ${endGen} generations observed · ${events.length} disturbance${events.length === 1 ? '' : 's'} · ${FORMAT_REASON(finishReason)}`;
    els.recordFooterSeed.textContent = String(rec.seed);
    els.recordEndReason.textContent = finishReason === 'sealed' ? `sealed early at generation ${endGen}` : `horizon reached at generation ${endGen}`;
    els.recordDeck.textContent = `Seed ${rec.seed} · ${endGen} of ${target} generations observed · ${events.length} disturbance${events.length === 1 ? '' : 's'}`;

    const finalFlora = Math.round(rec.plantCover * 100);
    const prey = rec.counts.prey;
    const pred = rec.counts.predator;
    let outcome;
    if (prey > 0 && pred > 0) outcome = finishReason === 'sealed' ? 'The slide is sealed with both lineages still moving.' : 'Two lineages persist at the horizon.';
    else if (prey === 0 && pred === 0) outcome = 'The glass is still. Both lineages are gone.';
    else if (prey === 0) outcome = 'The moths are lost; the shrikes keep their vigil.';
    else outcome = 'The shrikes are gone; the moths inherit the glass.';
    els.outcomeText.textContent = outcome;

    els.recordLedger.innerHTML = '';
    const rows = [
      ['Final flora', `${finalFlora}% cover`],
      ['Moths', `${fmt(prey)} <span class="soft">/ peak ${fmt(rec.history.preyPeak)}</span>`],
      ['Shrikes', `${fmt(pred)} <span class="soft">/ peak ${fmt(rec.history.predatorPeak)}</span>`],
      ['Births · moths / shrikes', `${fmt(rec.stats.births.prey)} / ${fmt(rec.stats.births.predator)}`],
      ['Taken by shrikes', fmt(rec.stats.deaths.prey.preyed)],
      ['Calamities weathered', fmt(events.length)],
      ['Generations observed', `${endGen} <span class="soft">/ ${target}</span>`],
      ['Mutation at birth', `${fmt1(rec.config.mutation)}%`],
    ];
    rows.forEach(([label, value]) => {
      const row = document.createElement('div');
      row.className = 'ledger-row';
      const dt = document.createElement('dt');
      dt.textContent = label;
      const dd = document.createElement('dd');
      dd.innerHTML = value;
      row.append(dt, dd);
      els.recordLedger.appendChild(row);
    });

    // Event list
    els.recordEvents.innerHTML = '';
    events.forEach((ev) => {
      const li = document.createElement('li');
      li.style.setProperty('--ev', eventColor(ev.type));
      const sw = document.createElement('i');
      sw.className = 'event-swatch';
      const num = document.createElement('span');
      num.className = 'e-num';
      num.textContent = ev.num;
      const name = document.createElement('span');
      name.className = 'e-name';
      name.textContent = ev.name;
      const span = document.createElement('span');
      span.className = 'e-span';
      span.textContent = ev.open ? `${ev.start}–${ev.end} · open` : `${ev.start}–${ev.end}`;
      li.append(sw, num, name, span);
      els.recordEvents.appendChild(li);
    });
    els.recordNoEvents.hidden = events.length > 0;
    els.recordEvents.hidden = events.length === 0;

    // Drift headlines
    els.recordDrift.innerHTML = '';
    const labels = { prey: 'Moths', predator: 'Shrikes' };
    const driftItems = [];
    for (const sp of ['prey', 'predator']) {
      for (const gene of GENE_DEFS) {
        const t = rec.traits[sp][gene.key];
        if (t.start === null || t.end === null) continue;
        driftItems.push({ sp, gene, start: t.start, end: t.end, delta: t.end - t.start, norm: Math.abs(t.end - t.start) / (gene.max - gene.min) });
      }
    }
    driftItems.sort((a, b) => b.norm - a.norm);
    driftItems.slice(0, 4).forEach((item) => {
      const li = document.createElement('li');
      const label = document.createElement('span');
      label.textContent = `${labels[item.sp]} · ${item.gene.name.toLowerCase()}`;
      const val = document.createElement('b');
      const arrow = item.delta >= 0 ? '↑' : '↓';
      val.textContent = `${geneValue(item.gene, item.start)} ${arrow} ${geneValue(item.gene, item.end)}`;
      li.append(label, val);
      els.recordDrift.appendChild(li);
    });
    if (!driftItems.length) {
      const li = document.createElement('li');
      li.textContent = 'No living genes remained to measure.';
      els.recordDrift.appendChild(li);
    }
    els.recordAsideNote.textContent = events.length
      ? 'Each disturbance is a hand upon the same inheritance. The record keeps both the curve and the drift.'
      : 'The calendar was left unarmed. The curves are inheritance alone.';

    buildTraitRows();
    els.recordFooterSeed.textContent = String(rec.seed);
    renderEventList();
  }

  function FORMAT_REASON(reason) {
    return reason === 'sealed' ? 'sealed by hand' : 'horizon reached';
  }

  function openRecord() {
    if (!world) return;
    if (!state.record) state.record = world.summary();
    if (!state.record) return;
    window.clearTimeout(state.recordTimer);
    hideHover();
    hideTooltip();
    buildRecord();
    els.record.hidden = false;
    state.recordOpen = true;
    state.returnFocus = document.activeElement;
    els.folio.inert = true;
    els.drawerHandle.inert = true;
    els.drawerScrim.inert = true;
    document.body.classList.add('record-open');
    window.requestAnimationFrame(() => {
      els.record.classList.add('is-open');
      window.setTimeout(() => {
        drawCharts();
        if (state.chartRefs.length) {
          state.chartRefs.forEach((ref, i) => {
            ref.canvas.style.animationDelay = `${0.08 + i * 0.04}s`;
          });
        }
        els.recordTitle.focus({ preventScroll: true });
      }, REDUCED ? 20 : 120);
    });
    announce('The record is open.');
  }

  function closeRecord(instant = false) {
    if (!state.recordOpen && !instant) return;
    state.recordOpen = false;
    els.record.classList.remove('is-open');
    document.body.classList.remove('record-open');
    els.folio.inert = false;
    els.drawerHandle.inert = false;
    els.drawerScrim.inert = false;
    const finish = () => {
      if (!state.recordOpen) els.record.hidden = true;
    };
    if (instant) finish();
    else window.setTimeout(finish, 700);
    if (state.returnFocus && state.returnFocus.focus && document.contains(state.returnFocus)) {
      state.returnFocus.focus({ preventScroll: true });
    } else {
      els.sealBtn.focus({ preventScroll: true });
    }
  }

  function hideRecord(instant = false) {
    if (!state.recordOpen && els.record.hidden) return;
    closeRecord(instant);
    window.clearTimeout(state.recordTimer);
  }

  function replaySlide() {
    closeRecord(true);
    startNewRun();
  }

  function newSeedRun() {
    const seed = nextSeed(world ? world.seed : Number(els.seedInput.value) || 4407);
    els.seedInput.value = String(seed);
    closeRecord(true);
    startNewRun();
  }

  /* ---------------------------------------------------------------
     Bindings
     --------------------------------------------------------------- */
  function bindControls() {
    document.querySelectorAll('.range').forEach((input) => {
      setRangeFill(input);
      input.addEventListener('input', () => {
        setRangeFill(input);
        if (input === els.mutationRange) {
          els.mutationValue.textContent = fmt1(Number(input.value));
          updateMutationNote();
          if (world) world.setMutation(Number(input.value));
          flashValue(els.mutationValue);
          drawSparks();
        } else if (input === els.regrowthRange) {
          els.regrowthValue.textContent = fmt1(Number(input.value));
          if (world) world.setRegrowth(Number(input.value));
          flashValue(els.regrowthValue);
          drawSparks();
        } else if (input === els.tempoRange) {
          applyTempo(Number(input.value), true);
        }
      });
      input.addEventListener('change', () => {
        if (input === els.tempoRange) applyTempo(Number(input.value), false);
      });
    });

    els.tempoRange.value = String(sliderFromSpeed(state.speed));
    setRangeFill(els.tempoRange);
    applyTempo(Number(els.tempoRange.value), false);

    els.seedReroll.addEventListener('click', () => {
      if (!world) return;
      const seed = nextSeed(world.seed);
      els.seedInput.value = String(seed);
      startNewRun();
    });
    els.seedInput.addEventListener('change', () => {
      const val = clamp(Math.round(Number(els.seedInput.value) || 4407), 1, 9999);
      els.seedInput.value = String(val);
      if (!world || val !== world.seed) startNewRun();
    });
    els.seedInput.addEventListener('keydown', (e) => {
      if (e.key === 'Enter') { e.preventDefault(); els.seedInput.blur(); }
    });

    els.horizonInput.addEventListener('change', () => applyHorizon());
    [els.droughtInput, els.plagueInput, els.bloomInput].forEach((input) => {
      input.addEventListener('change', () => {
        const type = input.id.replace('Input', '');
        applyInterval(type, Number(input.value), true);
      });
      input.addEventListener('keydown', (e) => {
        if (e.key === 'Enter') { e.preventDefault(); input.blur(); }
      });
    });
    els.instruments.addEventListener('click', (e) => {
      const step = e.target.closest('.step-btn');
      if (step) {
        const key = step.dataset.step;
        const dir = Number(step.dataset.dir);
        if (key === 'horizon') {
          els.horizonInput.value = String(clamp(Math.round(Number(els.horizonInput.value) || 240) + dir * 10, 40, 2000));
          applyHorizon();
        } else {
          const input = els[`${key}Input`];
          const current = clamp(Math.round(Number(input.value) || EVENT_DEFS[key].defaultInterval), 15, 400);
          input.value = String(current + dir * 5);
          applyInterval(key, Number(input.value), true);
        }
        return;
      }
      const toggle = e.target.closest('[data-toggle]');
      if (toggle) toggleCalamity(toggle);
    });

    els.holdBtn.addEventListener('click', toggleHold);
    els.stepBtn.addEventListener('click', stepGeneration);
    els.recastBtn.addEventListener('click', () => startNewRun());
    els.sealBtn.addEventListener('click', sealOrRecord);
    els.headlessBtn.addEventListener('click', runWithoutGlass);

    els.drawerToggle.addEventListener('click', () => setDrawer(document.documentElement.classList.contains('is-collapsed'), true));
    els.drawerClose.addEventListener('click', () => setDrawer(false, true));
    els.drawerHandle.addEventListener('click', () => setDrawer(true, true));
    els.drawerScrim.addEventListener('click', () => setDrawer(false, true));

    els.recordClose.addEventListener('click', () => closeRecord());
    els.recordReplay.addEventListener('click', replaySlide);
    els.recordNew.addEventListener('click', newSeedRun);

    els.worldCanvas.addEventListener('pointermove', onPointerMove);
    els.worldCanvas.addEventListener('pointerenter', onPointerMove);
    els.worldCanvas.addEventListener('pointerleave', () => {
      state.pointerInside = false;
      hideHover();
    });
    els.worldCanvas.addEventListener('pointerdown', hideTooltip, true);

    window.addEventListener('resize', debounce(() => {
      measureWorldCanvas();
      drawSparks();
      drawDial(performance.now());
      drawTimeline(performance.now());
      if (state.recordOpen) drawCharts();
    }, 140));

    new ResizeObserver(() => measureWorldCanvas()).observe(els.plate);
    new ResizeObserver(() => {
      if (state.recordOpen) drawCharts();
    }).observe(els.record);
    document.addEventListener('keydown', onKeyDown);
  }

  function updateMutationNote() {
    const m = Number(els.mutationRange.value);
    els.mutationNote.textContent = m === 0 ? 'no drift' : m < 5 ? 'faint drift' : m < 12 ? 'measured drift' : m < 18 ? 'strong drift' : 'wild drift';
  }

  function applyTempo(raw, redraw = true) {
    const speed = speedFromSlider(clamp(raw, 0, 100));
    state.speed = speed;
    els.tempoValue.textContent = speed.toFixed(1);
    updateTimeNote();
    if (redraw) drawSparks();
  }

  function applyHorizon() {
    if (!world) return;
    let value = clamp(Math.round(Number(els.horizonInput.value) || 240), 40, 2000);
    els.horizonInput.value = String(value);
    world.setTarget(value);
    els.horizonAside.textContent = `ends at ${value}`;
    drawSparks();
    drawTimeline(performance.now());
    updateCounts();
    updateDialReadouts();
    if (world.done && !state.finished) finishRun(world.finishReason || 'horizon');
  }

  function applyInterval(type, value, applyLive) {
    if (!world) return;
    const val = clamp(Math.round(value), 15, 400);
    const input = els[`${type}Input`];
    input.value = String(val);
    if (applyLive) world.setSchedule(type, { interval: val });
    drawSparks();
    drawDial(performance.now());
    drawTimeline(performance.now());
    updateDialReadouts();
  }

  function toggleCalamity(button) {
    const type = button.dataset.toggle;
    const armed = button.getAttribute('aria-checked') !== 'true';
    button.setAttribute('aria-checked', String(armed));
    button.setAttribute('aria-label', `${armed ? 'Disarm' : 'Arm'} ${EVENT_DEFS[type].name.toLowerCase()}`);
    const item = button.closest('.calamity-item');
    item?.classList.toggle('is-off', !armed);
    if (world) world.setSchedule(type, { armed });
    drawSparks();
    drawDial(performance.now());
    drawTimeline(performance.now());
    updateDialReadouts();
    announce(`${EVENT_DEFS[type].name} ${armed ? 'armed' : 'disarmed'}.`);
  }

  function onPointerMove(e) {
    if (!world || e.pointerType === 'touch') return;
    state.pointerInside = true;
    const rect = els.worldCanvas.getBoundingClientRect();
    state.pointerX = e.clientX - rect.left;
    state.pointerY = e.clientY - rect.top;
    updateHoverSelection();
  }

  function onKeyDown(e) {
    if (e.key === 'Escape') {
      hideTooltip();
      if (state.recordOpen) { e.preventDefault(); closeRecord(); return; }
      if (MOBILE.matches && !document.documentElement.classList.contains('is-collapsed')) {
        setDrawer(false); els.drawerToggle.focus();
      }
      return;
    }
    if (state.recordOpen) {
      if (e.key === 'Tab') trapRecordFocus(e);
      return;
    }
    const tag = (e.target.tagName || '').toLowerCase();
    if (tag === 'input' || tag === 'textarea' || tag === 'select' || tag === 'button' || e.target.isContentEditable) return;
    if (e.metaKey || e.ctrlKey || e.altKey) return;
    if (e.code === 'Space') { e.preventDefault(); toggleHold(); return; }
    const k = e.key.toLowerCase();
    if (k === 'r') { e.preventDefault(); startNewRun(); }
    else if (k === 'n') { e.preventDefault(); if (world) { els.seedInput.value = String(nextSeed(world.seed)); startNewRun(); } }
    else if (k === 'e') { e.preventDefault(); sealOrRecord(); }
    else if (k === 'h') { e.preventDefault(); runWithoutGlass(); }
    else if (k === '[') { e.preventDefault(); setTempoRaw(Number(els.tempoRange.value) - 5); }
    else if (k === ']') { e.preventDefault(); setTempoRaw(Number(els.tempoRange.value) + 5); }
  }

  function setTempoRaw(raw) {
    const v = clamp(raw, 0, 100);
    els.tempoRange.value = String(v);
    setRangeFill(els.tempoRange);
    applyTempo(v, true);
  }

  function trapRecordFocus(e) {
    const focusables = [...els.record.querySelectorAll('button:not([disabled]), [href], input:not([disabled]), [tabindex]:not([tabindex="-1"])')]
      .filter((el) => measureVisible(el));
    if (!focusables.length) return;
    const first = focusables[0];
    const last = focusables[focusables.length - 1];
    if (e.shiftKey && (document.activeElement === first || document.activeElement === els.recordTitle)) {
      e.preventDefault();
      last.focus();
    } else if (!e.shiftKey && document.activeElement === last) {
      e.preventDefault();
      first.focus();
    }
  }

  function debounce(fn, wait) {
    let t = 0;
    return (...args) => {
      window.clearTimeout(t);
      t = window.setTimeout(() => fn(...args), wait);
    };
  }

  /* ---------------------------------------------------------------
     Initialization
     --------------------------------------------------------------- */
  function init() {
    const params = new URLSearchParams(window.location.search);
    if (params.has('seed')) els.seedInput.value = String(clamp(Math.round(Number(params.get('seed')) || 4407), 1, 9999));
    if (params.has('gens')) els.horizonInput.value = String(clamp(Math.round(Number(params.get('gens')) || 240), 40, 2000));
    if (params.has('seed') || params.has('gens')) {
      // Reflect the URL parameters in the controls before creating the world.
      els.footerSeed.textContent = els.seedInput.value;
    }
    initPlantLayer();
    bindControls();
    bindTooltips();
    addHelpDescriptions();
    updateMutationNote();
    const collapsed = document.documentElement.classList.contains('is-collapsed');
    els.instruments.inert = collapsed;
    els.drawerHandle.inert = false;
    els.record.hidden = true;
    els.headlessVeil.hidden = true;
    if (MOBILE.matches) els.drawerScrim.hidden = false;
    startNewRun();
    if (!RAF_STARTED) requestAnimationFrame(loop);
    updateTransport();
  }

  let RAF_STARTED = false;
  function startLoop() {
    RAF_STARTED = true;
    requestAnimationFrame(loop);
  }

  // Start after the DOM has been laid out.
  init();
  startLoop();

  /* ---------------------------------------------------------------
     Public headless / control API
     --------------------------------------------------------------- */
  Object.defineProperty(window, 'VIVARIUM', {
    value: {
      version: 'IV',
      sim: SIM,
      runHeadless: (config) => SIM.runHeadless(config),
      createWorld: (config) => SIM.createWorld(config),
      get world() { return world; },
      get record() { return state.record; },
      get config() { return world ? world.config : null; },
      control: {
        pause,
        resume,
        toggleHold,
        recast: startNewRun,
        seal: () => finishRun('sealed', true),
        finish: () => finishRun('horizon', true),
        runWithoutGlass,
        openRecord,
        closeRecord,
        nextSeed: () => (world ? nextSeed(world.seed) : null),
      },
    },
    writable: false,
    configurable: false,
  });

  window.__VIVARIUM_READY__ = true;
})();
