    item?.classList.toggle('is-off', !armed);
    if (world) world.setSchedule(type, { armed });
    drawSparks();
    drawDial(performance.now());
    drawTimeline(performance.now());
    updateDialReadouts();
    announce(`${EVENT_DEFS[type].name} ${armed ? 'armed' : 'disarmed'}.`);
  }

  function onPointerMove(e) {
    if (!world || e.pointerType === 'touch') return;
    state.pointerInside = true;
    const rect = els.worldCanvas.getBoundingClientRect();
    state.pointerX = e.clientX - rect.left;
    state.pointerY = e.clientY - rect.top;
    updateHoverSelection();
  }

  function onKeyDown(e) {
    if (e.key === 'Escape') {
      hideTooltip();
      if (state.recordOpen) { e.preventDefault(); closeRecord(); return; }
      if (MOBILE.matches && !document.documentElement.classList.contains('is-collapsed')) {
        setDrawer(false); els.drawerToggle.focus();
      }
      return;
    }
    if (state.recordOpen) {
      if (e.key === 'Tab') trapRecordFocus(e);
      return;
    }
    const tag = (e.target.tagName || '').toLowerCase();
    if (tag === 'input' || tag === 'textarea' || tag === 'select' || tag === 'button' || e.target.isContentEditable) return;
    if (e.metaKey || e.ctrlKey || e.altKey) return;
    if (e.code === 'Space') { e.preventDefault(); toggleHold(); return; }
    const k = e.key.toLowerCase();
    if (k === 'r') { e.preventDefault(); startNewRun(); }
    else if (k === 'n') { e.preventDefault(); if (world) { els.seedInput.value = String(nextSeed(world.seed)); startNewRun(); } }
    else if (k === 'e') { e.preventDefault(); sealOrRecord(); }
    else if (k === 'h') { e.preventDefault(); runWithoutGlass(); }
    else if (k === '[') { e.preventDefault(); setTempoRaw(Number(els.tempoRange.value) - 5); }
    else if (k === ']') { e.preventDefault(); setTempoRaw(Number(els.tempoRange.value) + 5); }
  }

  function setTempoRaw(raw) {
    const v = clamp(raw, 0, 100);
    els.tempoRange.value = String(v);
    setRangeFill(els.tempoRange);
    applyTempo(v, true);
  }

  function trapRecordFocus(e) {
    const focusables = [...els.record.querySelectorAll('button:not([disabled]), [href], input:not([disabled]), [tabindex]:not([tabindex="-1"])')]
      .filter((el) => measureVisible(el));
    if (!focusables.length) return;
    const first = focusables[0];
    const last = focusables[focusables.length - 1];
    if (e.shiftKey && (document.activeElement === first || document.activeElement === els.recordTitle)) {
      e.preventDefault();
      last.focus();
    } else if (!e.shiftKey && document.activeElement === last) {
      e.preventDefault();
      first.focus();
    }
  }

  function debounce(fn, wait) {
    let t = 0;
    return (...args) => {
      window.clearTimeout(t);
      t = window.setTimeout(() => fn(...args), wait);
    };
  }

  /* ---------------------------------------------------------------
     Initialization
     --------------------------------------------------------------- */
  function init() {
    const params = new URLSearchParams(window.location.search);
    if (params.has('seed')) els.seedInput.value = String(clamp(Math.round(Number(params.get('seed')) || 4407), 1, 9999));
    if (params.has('gens')) els.horizonInput.value = String(clamp(Math.round(Number(params.get('gens')) || 240), 40, 2000));
