const fs = require('fs');

async function main() {
  const cmd = process.argv[2] || 'screenshot';
  const list = await (await fetch('http://127.0.0.1/json/list')).json();
  const target = list.find((t) => t.type === 'page' && t.url.includes('index.html')) || list.find((t) => t.type === 'page');
  if (!target) throw new Error('No page target');
  const ws = new WebSocket(target.webSocketDebuggerUrl);
  let nextId = 1;
  const pending = new Map();
  const consoleLines = [];
  const errors = [];
  ws.addEventListener('message', (event) => {
    const msg = JSON.parse(event.data);
    if (msg.id && pending.has(msg.id)) {
      const { resolve, reject } = pending.get(msg.id);
      pending.delete(msg.id);
      if (msg.error) reject(new Error(JSON.stringify(msg.error)));
      else resolve(msg.result);
      return;
    }
    if (msg.method === 'Runtime.consoleAPICalled') {
      consoleLines.push(`[console.${msg.params.type}] ` + msg.params.args.map((a) => a.value ?? a.description ?? a.type).join(' '));
    }
    if (msg.method === 'Runtime.exceptionThrown') {
      const d = msg.params.exceptionDetails;
      errors.push(`${d.text}: ${d.exception && d.exception.description || ''} @ ${d.url || ''}:${d.lineNumber}`);
    }
    if (msg.method === 'Log.entryAdded') {
      const e = msg.params.entry;
      if (e.level === 'error') errors.push(`[log] ${e.text} ${e.url || ''}`);
    }
  });
  await new Promise((res, rej) => { ws.addEventListener('open', res); ws.addEventListener('error', rej); });
  function send(method, params = {}) {
    return new Promise((resolve, reject) => {
      const id = nextId++;
      pending.set(id, { resolve, reject });
      ws.send(JSON.stringify({ id, method, params }));
    });
  }
  async function evaluate(expression, awaitPromise = false) {
    const r = await send('Runtime.evaluate', { expression, returnByValue: true, awaitPromise, userGesture: true });
    if (r.exceptionDetails) throw new Error(r.exceptionDetails.text + ' ' + (r.exceptionDetails.exception?.description || ''));
    return r.result.value;
  }
  await send('Runtime.enable');
  await send('Log.enable');
  await send('Page.enable');

  if (cmd === 'screenshot') {
    const width = Number(process.argv[3] || 1440);
    const height = Number(process.argv[4] || 900);
    const out = process.argv[5] || '<TMP>/viv-chrome/shot.png';
    const scale = Number(process.argv[6] || 2);
    await send('Emulation.setDeviceMetricsOverride', { width, height, deviceScaleFactor: scale, mobile: false });
    await new Promise((r) => setTimeout(r, 1200));
    const evalResult = await evaluate(`({ ready: window.__VIVARIUM_READY__ || false, title: document.title, gen: window.VIVARIUM?.world?.gen, w: innerWidth, h: innerHeight, record: !!window.VIVARIUM?.record, errors: [] })`);
    const shot = await send('Page.captureScreenshot', { format: 'png', captureBeyondViewport: false });
    fs.writeFileSync(out, Buffer.from(shot.data, 'base64'));
    console.log(JSON.stringify(evalResult));
    console.log('screenshot', out);
  } else if (cmd === 'eval') {
    const expr = process.argv[3];
    const value = await evaluate(expr, true);
    console.log(typeof value === 'string' ? value : JSON.stringify(value, null, 2));
  } else if (cmd === 'finish') {
    await evaluate(`VIVARIUM.control.finish()`);
    await new Promise((r) => setTimeout(r, 2000));
    const out = process.argv[3] || '<TMP>/viv-chrome/record.png';
    await send('Emulation.setDeviceMetricsOverride', { width: 1440, height: 900, deviceScaleFactor: 2, mobile: false });
    await new Promise((r) => setTimeout(r, 900));
    const shot = await send('Page.captureScreenshot', { format: 'png', captureBeyondViewport: false });
    fs.writeFileSync(out, Buffer.from(shot.data, 'base64'));
    console.log('record screenshot', out);
  }
  if (consoleLines.length) console.log('CONSOLE:\n' + consoleLines.join('\n'));
  if (errors.length) console.log('ERRORS:\n' + errors.join('\n'));
  ws.close();
}
main().catch((err) => { console.error(err); process.exit(1); });
EOF
