end=s.index('  /* ---------------------------------------------------------------\n     Chronograph canvas', start)
new_dial = '''  function drawDial(now) {
    if (!world) return;
    const prep = prepareCanvas(els.dialCanvas);
    if (!prep) return;
    const { ctx, w, h } = prep;
    const cx = w / 2;
    const cy = h / 2 + 4;
    const R = Math.min(w * 0.43, h * 0.45);
    const start = (135 * Math.PI) / 180;
    const sweep = (270 * Math.PI) / 180;
    const genFloat = world.gen + world.tickInGen / GEN_TICKS;
    const mono = (size) => `${size}px "SFMono-Regular", "SF Mono", Menlo, monospace`;
    const serif = (size) => `italic ${size}px "Iowan Old Style", "Palatino Linotype", Palatino, Georgia, serif`;

    ctx.save();
    // Center well keeps the engraving calm behind the readout.
    const well = ctx.createRadialGradient(cx, cy, 0, cx, cy, R * 0.55);
    well.addColorStop(0, 'rgba(9, 13, 10, 0.96)');
    well.addColorStop(0.7, 'rgba(9, 13, 10, 0.9)');
    well.addColorStop(1, 'rgba(9, 13, 10, 0)');
    ctx.fillStyle = well;
    ctx.beginPath();
    ctx.arc(cx, cy, R * 0.6, 0, TAU);
    ctx.fill();

    ctx.strokeStyle = 'rgba(233,227,209,0.14)';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.arc(cx, cy, R + 4, 0, TAU);
    ctx.stroke();
    ctx.strokeStyle = 'rgba(199,161,95,0.22)';
    ctx.beginPath();
    ctx.arc(cx, cy, R + 1, 0, TAU);
    ctx.stroke();

    // Graduations around the bezel
    for (let i = 0; i <= 72; i++) {
      const a = start + (i / 72) * sweep;
      const long = i % 6 === 0;
      const r1 = R + 1.5;
      const r2 = R + (long ? 7 : 4);
      ctx.strokeStyle = long ? 'rgba(199,161,95,0.48)' : 'rgba(233,227,209,0.15)';
      ctx.beginPath();
      ctx.moveTo(cx + Math.cos(a) * r1, cy + Math.sin(a) * r1);
      ctx.lineTo(cx + Math.cos(a) * r2, cy + Math.sin(a) * r2);
      ctx.stroke();
    }

    // Three concentric event arcs, gathered in the outer band.
    const types = EVENT_ORDER;
    const radii = [R - 13, R - 22, R - 31];
    for (let i = 0; i < types.length; i++) {
      const type = types[i];
      const def = EVENT_DEFS[type];
      const s = world.schedules[type];
      const radius = radii[i];
      ctx.beginPath();
      ctx.strokeStyle = 'rgba(233,227,209,0.1)';
      ctx.lineWidth = 1;
      ctx.arc(cx, cy, radius, start, start + sweep);
      ctx.stroke();
      if (!s.armed) {
        ctx.beginPath();
        ctx.strokeStyle = hexA(def.color, 0.2);
        ctx.setLineDash([1, 4]);
        ctx.arc(cx, cy, radius, start, start + sweep);
        ctx.stroke();
        ctx.setLineDash([]);
      } else {
        const active = world.activeEvents.find((e) => e.type === type);
