new_chart = '''  function drawPopulationChart() {
    if (!state.record) return;
    const prep = prepareCanvas(els.populationChart);
    if (!prep) return;
    const { ctx, w, h } = prep;
    const data = state.record.history;
    if (!data.gen.length) return;
    const padL = 42;
    const padR = 44;
    const padT = 27;
    const padB = 29;
    const plotW = Math.max(1, w - padL - padR);
    const plotH = Math.max(1, h - padT - padB);
    const lastGen = Math.max(1, data.gen[data.gen.length - 1]);
    const preyMax = niceMax(Math.max(12, (data.preyPeak || 0) * 1.08));
    const predMax = niceMax(Math.max(6, (data.predatorPeak || 0) * 1.2));
    const gap = 20;
    const topH = Math.max(80, plotH * 0.63);
    const bottomH = Math.max(44, plotH - topH - gap);
    const topBottom = padT + topH;
    const bottomTop = topBottom + gap;
    const bottomBottom = bottomTop + bottomH;
    const x = (g) => padL + (g / lastGen) * plotW;
    const yFlora = (v) => topBottom - clamp(v / 100, 0, 1) * topH;
    const yPrey = (v) => topBottom - clamp(v / preyMax, 0, 1) * topH;
    const yPred = (v) => bottomBottom - clamp(v / predMax, 0, 1) * bottomH;
    const mono = (size) => `${size}px "SFMono-Regular", "SF Mono", Menlo, monospace`;
    const serif = (size, italic = false) => `${italic ? 'italic ' : ''}${size}px "Iowan Old Style", "Palatino Linotype", Palatino, Georgia, serif`;

    // Disturbance washes and starts behind both bands.
    for (const ev of state.record.events) {
      if (ev.start > lastGen) continue;
      const def = EVENT_DEFS[ev.type];
      const x1 = x(ev.start);
      const x2 = x(Math.min(ev.end, lastGen));
      ctx.fillStyle = hexA(def.color, 0.035);
      ctx.fillRect(x1, padT, Math.max(1, x2 - x1), bottomBottom - padT);
      ctx.strokeStyle = hexA(def.color, 0.2);
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.moveTo(Math.round(x1) + 0.5, padT);
      ctx.lineTo(Math.round(x1) + 0.5, bottomBottom);
      ctx.stroke();
      ctx.fillStyle = hexA(def.color, 0.85);
      ctx.beginPath();
      ctx.moveTo(x1, padT - 11);
      ctx.lineTo(x1 + 2.6, padT - 8.2);
      ctx.lineTo(x1, padT - 5.4);
      ctx.lineTo(x1 - 2.6, padT - 8.2);
      ctx.closePath();
      ctx.fill();
    }

    // Upper band: flora cover and moths.
    ctx.font = mono(7.5);
    ctx.textBaseline = 'middle';
    for (const f of [0, 0.5, 1]) {
      const yy = topBottom - topH * f;
      ctx.strokeStyle = f === 1 ? 'rgba(233,227,209,0.15)' : 'rgba(233,227,209,0.075)';
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.moveTo(padL, Math.round(yy) + 0.5);
      ctx.lineTo(padL + plotW, Math.round(yy) + 0.5);
      ctx.stroke();
      ctx.textAlign = 'right';
      ctx.fillStyle = 'rgba(156,187,119,0.7)';
      ctx.fillText(String(Math.round(100 * f)), padL - 9, yy);
      ctx.textAlign = 'left';
      ctx.fillStyle = 'rgba(226,189,123,0.68)';
      ctx.fillText(fmt(preyMax * f), padL + plotW + 9, yy);
    }
    // Lower band: shrikes on a magnified scale.
    for (const f of [0, 0.5, 1]) {
      const yy = bottomBottom - bottomH * f;
      ctx.strokeStyle = f === 1 ? 'rgba(233,227,209,0.12)' : 'rgba(233,227,209,0.055)';
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.moveTo(padL, Math.round(yy) + 0.5);
      ctx.lineTo(padL + plotW, Math.round(yy) + 0.5);
      ctx.stroke();
      ctx.textAlign = 'right';
      ctx.fillStyle = 'rgba(215,116,93,0.66)';
      ctx.fillText(String(Math.round(predMax * f)), padL - 9, yy);
    }

    // Band captions.
    ctx.textAlign = 'left';
    ctx.textBaseline = 'bottom';
    ctx.fillStyle = 'rgba(156,187,119,0.8)';
    ctx.fillText('FLORA · % COVER', padL, padT - 7);
    ctx.textAlign = 'right';
    ctx.fillStyle = 'rgba(226,189,123,0.8)';
    ctx.fillText('MOTHS · COUNT', padL + plotW, padT - 7);
    ctx.textAlign = 'left';
    ctx.fillStyle = 'rgba(215,116,93,0.8)';
    ctx.fillText('SHRIKES · COUNT', padL, bottomTop - 7);
    ctx.textAlign = 'right';
    ctx.fillStyle = 'rgba(233,227,209,0.28)';
    ctx.fillText(`PEAK ${fmt(data.predatorPeak)}`, padL + plotW, bottomTop - 7);

    // Upper band contents.
    ctx.save();
    ctx.beginPath();
    ctx.rect(padL, padT - 1, plotW, topH + 2);
    ctx.clip();
    ctx.beginPath();
    let first = true;
    for (let i = 0; i < data.gen.length; i++) {
      const xx = x(data.gen[i]);
      const yy = yFlora(data.flora[i]);
      if (first) { ctx.moveTo(xx, yy); first = false; } else ctx.lineTo(xx, yy);
    }
    ctx.lineTo(x(lastGen), topBottom);
    ctx.lineTo(x(0), topBottom);
    ctx.closePath();
    const plantGrad = ctx.createLinearGradient(0, padT, 0, topBottom);
    plantGrad.addColorStop(0, 'rgba(156,187,119,0.16)');
    plantGrad.addColorStop(0.6, 'rgba(156,187,119,0.06)');
    plantGrad.addColorStop(1, 'rgba(156,187,119,0.008)');
    ctx.fillStyle = plantGrad;
    ctx.fill();
    ctx.beginPath();
    first = true;
    for (let i = 0; i < data.gen.length; i++) {
      const xx = x(data.gen[i]);
      const yy = yFlora(data.flora[i]);
      if (first) { ctx.moveTo(xx, yy); first = false; } else ctx.lineTo(xx, yy);
    }
    ctx.strokeStyle = 'rgba(156,187,119,0.78)';
    ctx.lineWidth = 1.1;
    ctx.stroke();
    ctx.beginPath();
    first = true;
    for (let i = 0; i < data.gen.length; i++) {
      const xx = x(data.gen[i]);
      const yy = yPrey(data.prey[i]);
      if (first) { ctx.moveTo(xx, yy); first = false; } else ctx.lineTo(xx, yy);
    }
    ctx.strokeStyle = '#e2bd7b';
    ctx.lineWidth = 1.5;
    ctx.globalAlpha = 0.96;
    ctx.stroke();
    ctx.globalAlpha = 1;
    ctx.beginPath();
    ctx.fillStyle = '#e2bd7b';
    ctx.arc(x(lastGen), yPrey(data.prey[data.prey.length - 1]), 2.2, 0, TAU);
    ctx.fill();
    ctx.restore();

    // Lower band contents.
    ctx.save();
    ctx.beginPath();
    ctx.rect(padL, bottomTop - 1, plotW, bottomH + 2);
    ctx.clip();
    ctx.beginPath();
    for (let i = 0; i < data.gen.length; i++) {
      const xx = x(data.gen[i]);
      const yy = yPred(data.predator[i]);
      if (i === 0) ctx.moveTo(xx, yy); else ctx.lineTo(xx, yy);
    }
    ctx.lineTo(x(lastGen), bottomBottom);
    ctx.lineTo(x(0), bottomBottom);
    ctx.closePath();
    const predGrad = ctx.createLinearGradient(0, bottomTop, 0, bottomBottom);
    predGrad.addColorStop(0, 'rgba(215,116,93,0.16)');
    predGrad.addColorStop(1, 'rgba(215,116,93,0.01)');
    ctx.fillStyle = predGrad;
    ctx.fill();
    ctx.beginPath();
    for (let i = 0; i < data.gen.length; i++) {
      const xx = x(data.gen[i]);
      const yy = yPred(data.predator[i]);
      if (i === 0) ctx.moveTo(xx, yy); else ctx.lineTo(xx, yy);
    }
    ctx.strokeStyle = '#d7745d';
    ctx.lineWidth = 1.45;
    ctx.stroke();
    ctx.beginPath();
    ctx.fillStyle = '#d7745d';
    ctx.arc(x(lastGen), yPred(data.predator[data.predator.length - 1]), 2.1, 0, TAU);
    ctx.fill();
    ctx.restore();

    // X axis
    ctx.font = mono(7.5);
    ctx.fillStyle = 'rgba(233,227,209,0.35)';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'top';
    for (let i = 0; i <= 4; i++) {
      const g = Math.round((lastGen * i) / 4);
      const xx = x(g);
      ctx.strokeStyle = 'rgba(233,227,209,0.11)';
      ctx.beginPath();
      ctx.moveTo(Math.round(xx) + 0.5, bottomBottom);
      ctx.lineTo(Math.round(xx) + 0.5, bottomBottom + 4);
      ctx.stroke();
      ctx.fillText(String(g), xx, bottomBottom + 8);
    }
    ctx.textAlign = 'right';
    ctx.fillStyle = 'rgba(233,227,209,0.26)';
    ctx.fillText('GENERATIONS', padL + plotW, bottomBottom + 20);

    // Loss annotations inside the relevant band.
    const findLoss = (key) => {
      let seen = false;
      for (let i = 0; i < data.gen.length; i++) {
        if (data[key][i] > 0) seen = true;
        else if (seen) return data.gen[i];
      }
      return null;
    };
    const preyLoss = findLoss('prey');
    const predatorLoss = findLoss('predator');
    ctx.font = mono(7);
    ctx.textAlign = 'left';
    ctx.textBaseline = 'bottom';
    if (preyLoss !== null) {
      ctx.fillStyle = 'rgba(226,189,123,0.62)';
      ctx.fillText(`MOTHS LOST · GEN ${preyLoss}`, padL + 4, topBottom - 5);
    }
    if (predatorLoss !== null) {
      ctx.fillStyle = 'rgba(215,116,93,0.72)';
      ctx.fillText(`SHRIKES LOST · GEN ${predatorLoss}`, padL + 4, bottomBottom - 5);
    }

    els.populationChart.setAttribute(
      'aria-label',
      `Population curves. Flora ends at ${Math.round(data.flora[data.flora.length - 1])} percent cover. Moths end at ${data.prey[data.prey.length - 1]}, peak ${data.preyPeak}; shrikes end at ${data.predator[data.predator.length - 1]}, peak ${data.predatorPeak}. Disturbance bands are marked.`
    );
    void serif;
  }

