{"command": "cat > dev/cdp2.js <<'EOF'
const fs = require('fs');
async function main() {
  const [,, widthArg, heightArg, out, mode='app', extra=''] = process.argv;
  const width = Number(widthArg || 390), height = Number(heightArg || 844);
  const list = await (await fetch('http://127.0.0.1/json/list')).json();
  const target = list.find((t) => t.type === 'page' && t.url.includes('index.html')) || list.find((t) => t.type === 'page');
  if (!target) throw new Error('No page target');
  const ws = new WebSocket(target.webSocketDebuggerUrl);
  let nextId = 1; const pending = new Map(); const errors = []; const logs = [];
  ws.addEventListener('message', (event) => {
    const msg = JSON.parse(event.data);
    if (msg.id && pending.has(msg.id)) {
      const p = pending.get(msg.id); pending.delete(msg.id);
      if (msg.error) p.reject(new Error(JSON.stringify(msg.error))); else p.resolve(msg.result);
      return;
    }
    if (msg.method === 'Runtime.exceptionThrown') {
      const d=msg.params.exceptionDetails; errors.push(`${d.text}: ${d.exception?.description||''} @ ${d.url}:${d.lineNumber}`);
    }
    if (msg.method === 'Runtime.consoleAPICalled') logs.push(msg.params.args.map(a=>a.value??a.description).join(' '));
  });
  await new Promise((res, rej) => { ws.addEventListener('open', res); ws.addEventListener('error', rej); });
  const send = (method, params={}) => new Promise((resolve,reject)=>{ const id=nextId++; pending.set(id,{resolve,reject}); ws.send(JSON.stringify({id,method,params})); });
  const evalJS = async (expression) => {
    const r = await send('Runtime.evaluate',{expression,returnByValue:true,awaitPromise:true,userGesture:true});
    if (r.exceptionDetails) throw new Error((r.exceptionDetails.exception?.description||r.exceptionDetails.text));
    return r.result.value;
  };
  await send('Runtime.enable'); await send('Page.enable'); await send('Log.enable');
  await send('Emulation.setDeviceMetricsOverride', { width, height, deviceScaleFactor: 2, mobile: width < 800 });
  await send('Page.reload', { ignoreCache: true });
  const start = Date.now();
  while (Date.now() - start < 8000) {
    await new Promise(r=>setTimeout(r,150));
    try { const ready = await evalJS('!!window.__VIVARIUM_READY__'); if (ready) break; } catch {}
  }
  await new Promise(r=>setTimeout(r, 900));
  if (mode === 'drawer') {
    await evalJS(`document.getElementById('drawerHandle').click()`);
    await new Promise(r=>setTimeout(r, 900));
  } else if (mode === 'record') {
    await evalJS(`(()=>{ VIVARIUM.control.pause(); for(let g=0;g<240;g++){ for(let i=0;i<12;i++) VIVARIUM.world.step(); } VIVARIUM.control.finish(); })()`);
    await new Promise(r=>setTimeout(r, 1800));
  } else if (mode === 'scrolled') {
    await evalJS(`window.scrollTo(0, Number(${JSON.stringify(height)}) * 0.55)`);
    await new Promise(r=>setTimeout(r, 500));
  } else if (mode === 'custom') {
    await evalJS(extra);
    await new Promise(r=>setTimeout(r, 1200));
  }
  const result = await evalJS(`({ready:window.__VIVARIUM_READY__, gen:window.VIVARIUM?.world?.gen, inner:[innerWidth,innerHeight], scroll:[document.documentElement.scrollWidth,document.documentElement.scrollHeight], rec:!!window.VIVARIUM?.record, collapsed:document.documentElement.classList.contains('is-collapsed'), drawer:document.getElementById('drawerSlot')?.getBoundingClientRect().toJSON()})`);
  const shot = await send('Page.captureScreenshot',{format:'png',captureBeyondViewport:false});
  fs.writeFileSync(out, Buffer.from(shot.data,'base64'));
  console.log(JSON.stringify(result,null,2));
  if (errors.length) console.log('ERRORS\n'+errors.join('\n'));
  if (logs.length) console.log('LOGS\n'+logs.slice(-20).join('\n'));
  ws.close();
}
main().catch(e=>{console.error(e);process.exit(1);});
EOF
