{"command": "cat > dev/a11y.js <<'EOF'
const fs = require('fs');
(async () => {
  const list = await (await fetch('http://127.0.0.1/json/list')).json();
  const target = list.find(t => t.type==='page' && t.url.includes('index.html'));
  const ws = new WebSocket(target.webSocketDebuggerUrl);
  let nextId=1; const pending=new Map(); const errors=[];
  ws.addEventListener('message', ev => {
    const m=JSON.parse(ev.data);
    if(m.id&&pending.has(m.id)){const p=pending.get(m.id);pending.delete(m.id);m.error?p.reject(new Error(JSON.stringify(m.error))):p.resolve(m.result);return;}
    if(m.method==='Runtime.exceptionThrown'){const d=m.params.exceptionDetails;errors.push(`${d.text}: ${d.exception?.description||''}`);}
  });
  await new Promise((res,rej)=>{ws.addEventListener('open',res);ws.addEventListener('error',rej);});
  const send=(method,params={})=>new Promise((resolve,reject)=>{const id=nextId++;pending.set(id,{resolve,reject});ws.send(JSON.stringify({id,method,params}));});
  const ev=async(expression)=>{const r=await send('Runtime.evaluate',{expression,returnByValue:true,awaitPromise:true,userGesture:true});if(r.exceptionDetails)throw new Error(r.exceptionDetails.exception?.description||r.exceptionDetails.text);return r.result.value;};
  await send('Runtime.enable'); await send('Page.enable');
  await send('Emulation.setDeviceMetricsOverride',{width:1440,height:900,deviceScaleFactor:2,mobile:false});
  await send('Page.reload',{ignoreCache:true});
  for(let i=0;i<40;i++){await new Promise(r=>setTimeout(r,150)); try{if(await ev('!!window.__VIVARIUM_READY__'))break;}catch{}}
  await new Promise(r=>setTimeout(r,600));
  const key = async (key, code, vk, modifiers=0) => {
    await send('Input.dispatchKeyEvent',{type:'keyDown',key,code,windowsVirtualKeyCode:vk,nativeVirtualKeyCode:vk,modifiers});
    await send('Input.dispatchKeyEvent',{type:'keyUp',key,code,windowsVirtualKeyCode:vk,nativeVirtualKeyCode:vk,modifiers});
    await new Promise(r=>setTimeout(r,150));
  };
  const active = () => ev(`(() => { const a=document.activeElement; const tip=document.getElementById('tooltip'); return {tag:a.tagName, id:a.id, label:a.getAttribute('aria-label')||a.textContent.trim().slice(0,40), tip: tip.classList.contains('is-visible')?tip.innerText.slice(0,90):null}; })()`);
  await ev(`document.body.focus()`);
  const seq=[];
  for(let i=0;i<10;i++){ await key('Tab','Tab',9); seq.push(await active()); }
  // Shortcut tests (focus currently a control; blur first)
  await ev(`document.activeElement.blur()`);
  await key(' ','Space',32);
  const afterSpace = await ev(`document.getElementById('statusText').textContent`);
  await key(' ','Space',32);
  const afterSpace2 = await ev(`document.getElementById('statusText').textContent`);
  const seedBefore = await ev(`VIVARIUM.world.seed`);
  await ev(`document.activeElement.blur()`);
  await key('n','KeyN',78);
  const seedAfter = await ev(`VIVARIUM.world.seed`);
  const tempoBefore = await ev(`document.getElementById('tempoValue').textContent`);
  await key(']','BracketRight',221);
  const tempoAfter = await ev(`document.getElementById('tempoValue').textContent`);
  await ev(`document.activeElement.blur()`);
  await key('e','KeyE',69);
  await new Promise(r=>setTimeout(r,1400));
  const afterE = await ev(`({status:document.getElementById('statusText').textContent, rec:document.getElementById('record').classList.contains('is-open'), focus:document.activeElement.id})`);
  // focus trap: Tab from title, Shift+Tab from title
  await key('Tab','Tab',9);
  const recFocus1 = await active();
  await ev(`document.getElementById('recordTitle').focus()`);
  await key('Tab','Tab',9,8);
  const recFocus2 = await active();
  await key('Escape','Escape',27);
  await new Promise(r=>setTimeout(r,900));
  const afterEsc = await ev(`({rec:document.getElementById('record').classList.contains('is-open'), hidden:document.getElementById('record').hidden, focus:document.activeElement.id})`);
  await send('Page.captureScreenshot',{format:'png'}).then(s=>fs.writeFileSync('<TMP>/viv-chrome/a11y_after.png',Buffer.from(s.data,'base64')));
  console.log(JSON.stringify({seq, afterSpace, afterSpace2, seedBefore, seedAfter, tempoBefore, tempoAfter, afterE, recFocus1, recFocus2, afterEsc, errors},null,2));
  ws.close();
})();
EOF
