{"command": "cat > dev/perf.js <<'EOF'
(async () => {
  const list = await (await fetch('http://127.0.0.1/json/list')).json();
  const target = list.find(t => t.type==='page' && t.url.includes('index.html'));
  const ws = new WebSocket(target.webSocketDebuggerUrl);
  let nextId=1; const pending=new Map(); const errors=[];
  ws.addEventListener('message', ev=>{const m=JSON.parse(ev.data); if(m.id&&pending.has(m.id)){const p=pending.get(m.id);pending.delete(m.id);m.error?p.reject(new Error(JSON.stringify(m.error))):p.resolve(m.result);return;} if(m.method==='Runtime.exceptionThrown'){const d=m.params.exceptionDetails;errors.push(d.text);}});
  await new Promise((res,rej)=>{ws.addEventListener('open',res);ws.addEventListener('error',rej);});
  const send=(method,params={})=>new Promise((resolve,reject)=>{const id=nextId++;pending.set(id,{resolve,reject});ws.send(JSON.stringify({id,method,params}));});
  const ev=async(expression)=>{const r=await send('Runtime.evaluate',{expression,returnByValue:true,awaitPromise:true,userGesture:true});if(r.exceptionDetails)throw new Error(r.exceptionDetails.exception?.description||r.exceptionDetails.text);return r.result.value;};
  await send('Runtime.enable'); await send('Page.enable');
  await send('Emulation.setDeviceMetricsOverride',{width:1440,height:900,deviceScaleFactor:2,mobile:false});
  await send('Page.reload',{ignoreCache:true});
  for(let i=0;i<50;i++){await new Promise(r=>setTimeout(r,150));try{if(await ev('!!window.__VIVARIUM_READY__'))break;}catch{}}
  await new Promise(r=>setTimeout(r,500));
  const setup = await ev(`(() => {
    VIVARIUM.control.pause();
    const h=document.getElementById('horizonInput'); h.value='1000'; h.dispatchEvent(new Event('change',{bubbles:true}));
    const t=document.getElementById('tempoRange'); t.value='100'; t.dispatchEvent(new Event('input',{bubbles:true}));
    let guard=20000; while(VIVARIUM.world.gen<180 && guard-->0) VIVARIUM.world.step();
    VIVARIUM.control.resume();
    return {gen:VIVARIUM.world.gen, prey:VIVARIUM.world.prey.length, pred:VIVARIUM.world.predators.length, target:VIVARIUM.world.target};
  })()`);
  const measure = await ev(`(async () => {
    const intervals=[]; let last=performance.now(); let frames=0; const start=performance.now();
    await new Promise((resolve)=>{ const loop=(now)=>{ intervals.push(now-last); last=now; frames++; if(now-start<2500) requestAnimationFrame(loop); else resolve(); }; requestAnimationFrame(loop); });
    const sorted=[...intervals].sort((a,b)=>a-b);
    const avg=intervals.reduce((a,b)=>a+b,0)/intervals.length;
    const dropped=intervals.filter(v=>v>25).length;
    return {frames, avgMs:+avg.toFixed(2), p50:+sorted[Math.floor(sorted.length*0.5)].toFixed(2), p95:+sorted[Math.floor(sorted.length*0.95)].toFixed(2), max:+sorted.at(-1).toFixed(2), over25: dropped, gen:VIVARIUM.world.gen, prey:VIVARIUM.world.prey.length, pred:VIVARIUM.world.predators.length};
  })()`);
  console.log(JSON.stringify({setup, measure, errors}, null, 2));
  ws.close();
})();
EOF
node dev/perf.js 2>&1 | tail -40", "description": "Measure frame timing at high speed and population"}

